// WAVES & OPTICS
const waves = {
  string: waveString,
  translong: { ...waveString, means: 'Transverse waves oscillate perpendicular to travel (like a string); longitudinal waves oscillate along travel (like sound).', explore: 'Polarisation direction, compression/rarefaction, and medium type.', what: 'In a transverse wave the medium moves sideways to the wave\'s direction; in a longitudinal wave it moves back and forth along the direction.', name: 'Transverse — across; longitudinal — lengthwise.', physical: 'Water surface waves are mostly transverse; sound is longitudinal (pressure compressions).', quick: 'Transverse: shake sideways as it moves forward (string). Longitudue: push/pull along the motion (slinky, sound).', physics: 'Both satisfy the wave equation; the difference is the direction of oscillation relative to propagation.', math: 'Same v = √(restoring/inertia) relation; only the displacement component differs.', equations: [{ eq: 'v = √(restoring / inertia)', label: 'Generic wave speed' }], calculated: ['Wave speed', 'Polarisation direction', 'Compression pattern'], used: 'Sound (longitudinal), light (transverse), seismic P & S waves.', observe: 'Transverse waves can be polarised; longitudinal cannot.', why: 'The medium\'s restoring force direction sets whether displacement is across or along the wave.', assumptions: ['Linear medium', 'Isotropic'], limitations: ['Real waves are often mixed', 'Surface waves are combinations'], controls: { 'Polarisation': { desc: 'Direction of oscillation relative to travel.', unit: '—' } }, viz: { 'Displacement pattern': 'Sideways (transverse) or compression (longitudinal).' } },
  superposition: { means: 'Superposition is the principle that when two waves meet, the total displacement is the sum of the individual displacements.', explore: 'Constructive and destructive interference, phase, and resultant waves.', what: 'Where two waves overlap, just add their heights. In phase → bigger (constructive); out of phase → cancel (destructive).', name: 'Super- (above) + position — placing on top; adding displacements.', physical: 'Waves pass through each other unchanged; while overlapping they add linearly.', quick: 'Two waves add like numbers: same phase = bigger, opposite phase = flat. After meeting, each continues as if nothing happened.', physics: 'y_total = y₁ + y₂. Constructive when phase Δφ = 0; destructive when Δφ = π.', math: 'For equal frequencies, amplitude ranges from |A₁−A₂| to A₁+A₂ depending on phase.', equations: [{ eq: 'y = y₁ + y₂', label: 'Superposition' }, { eq: 'A = √(A₁² + A₂² + 2A₁A₂ cosΔφ)', label: 'Resultant amplitude' }], calculated: ['Resultant wave', 'Interference pattern', 'Beat frequency'], used: 'Noise cancellation, interferometry, holography, music beats.', observe: 'Two identical in-phase waves double; opposite phase gives silence.', why: 'Phase difference determines whether peaks align (reinforce) or oppose (cancel).', assumptions: ['Linear medium', 'Waves don\'t interact non-linearly'], limitations: ['Large amplitudes cause non-linear effects', 'Real media absorb and disperse'], controls: { 'Phase difference (Δφ)': { desc: 'Sets constructive vs destructive.', unit: 'rad' } }, viz: { 'Sum wave': 'Constructive peaks or destructive flat zones.' } },
  interference: { means: 'Interference is the pattern of constructive and destructive overlap that results when coherent waves superpose.', explore: 'Fringe spacing, coherence, path-length differences, and intensity patterns.', what: 'Two coherent sources produce stable bright (constructive) and dark (destructive) regions where path differences are integer or half-integer wavelengths.', name: 'Inter-fere — to strike against; waves affecting each other.', physical: 'Bright fringes where Δpath = mλ; dark where Δpath = (m+½)λ.', quick: 'Overlapping coherent waves make stable light/dark bands — bright where paths differ by a whole wavelength, dark where by a half.', physics: 'For two slits: intensity I ∝ cos²(πd sinθ/λ). Fringe spacing Δy = λL/d.', math: 'Path difference d sinθ = mλ (bright) or (m+½)λ (dark).', equations: [{ eq: 'd sinθ = m λ', label: 'Bright fringes' }, { eq: 'Δy = λ L / d', label: 'Fringe spacing', where: 'L = screen distance, d = slit separation' }], calculated: ['Fringe positions', 'Intensity pattern', 'Coherence effects'], used: 'Interferometers, holography, LIGO, thin-film colours, optical testing.', observe: 'Wider slit spacing → narrower fringes; longer wavelength → wider fringes.', why: 'A larger path difference shifts where peaks align; wavelength sets the scale of the pattern.', assumptions: ['Coherent sources', 'Monochromatic light', 'Far-field (Fraunhofer)'], limitations: ['Real sources have finite coherence', 'Near-field differs', 'Multiple slits add complexity'], controls: { 'Wavelength (λ)': { desc: 'Sets fringe scale; longer λ = wider fringes.', unit: 'nm' }, 'Slit separation (d)': { desc: 'Wider d = narrower fringes.', unit: 'μm' } }, viz: { 'Intensity pattern': 'Bright/dark bands; spacing ∝ λ/d.' } },
  standing: { means: 'A standing wave is a pattern that oscillates in place — formed by two identical waves travelling in opposite directions.', explore: 'Nodes, antinodes, harmonics, and resonance on bounded media.', what: 'When reflected and incident waves superpose with the right frequency, the medium oscillates up and down without travelling — fixed nodes (zero motion) and antinodes (max motion).', name: 'Standing — the wave pattern stays in place rather than travelling.', physical: 'Only certain frequencies (harmonics) fit the boundary conditions: f_n = n v/(2L) for fixed ends.', quick: 'A wave that doesn\'t travel — it just bobs in place. Fixed points (nodes) never move; midpoints (antinodes) move most. Only specific frequencies fit.', physics: 'Resonance of the medium: the boundary forces nodes at the ends, selecting discrete modes.', math: 'y(x,t) = 2A sin(kx) cos(ωt) — a spatial sine times a temporal cosine.', equations: [{ eq: 'f_n = n v / (2L)', label: 'Harmonics (fixed ends)', where: 'n = 1,2,3…' }, { eq: 'y = 2A sin(kx) cos(ωt)', label: 'Standing-wave form' }], calculated: ['Mode shapes', 'Resonant frequencies', 'Node/antinode positions'], used: 'String & wind instruments, microwave cavities, lasers, architectural acoustics.', observe: 'Higher harmonics add more nodes; only resonant frequencies persist.', why: 'Boundaries reflect waves; only frequencies whose half-wavelength fits the length reinforce into a stable pattern.', assumptions: ['Fixed/free boundaries', 'Lossless', 'Linear'], limitations: ['Real strings damp; only approximate standing waves', 'Coupling to air radiates energy'], controls: { 'Length (L)': { desc: 'Sets allowed frequencies; shorter L = higher pitches.', unit: 'm' }, 'Tension (T)': { desc: 'Sets wave speed v = √(T/μ); higher T = higher harmonics.', unit: 'N' } }, viz: { 'Mode shape': 'Nodes (still) and antinodes (moving) along the length.' } },
  beats: { means: 'Beats are a slow amplitude pulsing heard when two close frequencies superpose.', explore: 'Beat frequency, the two source frequencies, and the envelope.', what: 'Two tones of nearly equal frequency alternately reinforce and cancel, producing a "wah-wah" at the difference frequency.', name: 'Beat — a rhythmic pulsing.', physical: 'Beat frequency f_beat = |f₁ − f₂|. The envelope oscillates at the difference of the two frequencies.', quick: 'Two close tones pulse loudly/softly at their difference frequency. Tune instruments by zeroing the beat.', physics: 'cos(2πf₁t)+cos(2πf₂t) = 2cos(π(f₁−f₂)t)cos(π(f₁+f₂)t) — a fast carrier times a slow envelope.', math: 'f_beat = |f₁ − f₂|; the perceived pitch is the average (f₁+f₂)/2.', equations: [{ eq: 'f_beat = |f₁ − f₂|', label: 'Beat frequency' }], calculated: ['Beat rate', 'Envelope shape'], used: 'Tuning instruments, heterodyne radios, Doppler shift detection.', observe: 'As the two frequencies approach, the beat slows; at equality it vanishes.', why: 'Closer frequencies take longer to drift in/out of phase, so the beat slows.', assumptions: ['Both tones audible', 'Linear superposition'], limitations: ['Only works for close frequencies', 'Loudness perception is non-linear'], controls: { 'Frequency gap (Δf)': { desc: 'Sets the beat rate directly.', unit: 'Hz' } }, viz: { 'Amplitude envelope': 'Slow pulsing at f_beat around the fast carrier.' } },
  doppler: { means: 'The Doppler effect is the shift in observed frequency when source and observer move relative to each other.', explore: 'Approach (higher pitch), recede (lower pitch), and the source/observer speeds.', what: 'Motion toward you compresses wavefronts (higher frequency); motion away stretches them (lower frequency).', name: 'Named after Christian Doppler (1842).', physical: 'f\' = f (v ± v_obs)/(v ∓ v_src) for sound; relativistic form for light.', quick: 'A siren rises in pitch as it approaches and drops as it passes — wavefronts bunch up or spread out due to relative motion.', physics: 'For sound: f\' = f (v + v_o)/(v − v_s) (approaching). For light (relativistic): f\'/f = √((1±β)/(1∓β)).', math: 'The shift Δf/f ≈ v/c for small speeds (light).', equations: [{ eq: "f' = f (v ± v_o)/(v ∓ v_s)", label: 'Sound Doppler' }, { eq: "f' = f √((1+β)/(1−β))", label: 'Relativistic (light)' }], calculated: ['Observed frequency', 'Shift magnitude'], used: 'Radar guns, astronomy (redshift), medical ultrasound, sirens, weather radar.', observe: 'Faster approach → higher pitch; faster recession → lower pitch.', why: 'Motion toward you squeezes wavefronts together (shorter effective wavelength); motion away stretches them.', assumptions: ['Constant velocities', 'Stationary medium (for sound)'], limitations: ['Real sources accelerate', 'Medium motion complicates sound Doppler', 'Relativistic form needed for light at high speed'], controls: { 'Source speed (v_s)': { desc: 'Toward observer raises pitch; away lowers it.', unit: 'm/s' }, 'Observer speed (v_o)': { desc: 'Toward source raises pitch; away lowers it.', unit: 'm/s' } }, viz: { 'Wavefronts': 'Bunched ahead of an approaching source, spread behind.' } },
  sound: { means: 'Sound is a longitudinal pressure wave travelling through a medium (air, water, solids).', explore: 'Pressure compressions, wavelength, speed, intensity, and the decibel scale.', what: 'A vibrating source compresses and rarefies the air; these pressure pulses travel outward at the speed of sound.', name: 'Sound — from Latin sonus.', physical: 'Speed depends on the medium: ~343 m/s in air, ~1480 m/s in water, ~5000 m/s in steel. Intensity ∝ amplitude², measured in dB.', quick: 'Sound = travelling pressure squeezes. Faster in denser/stiffer media. Loudness is logarithmic (decibels).', physics: 'v = √(B/ρ) (bulk modulus over density). Intensity I ∝ p²; dB = 10 log₁₀(I/I₀).', math: 'Pressure variation p(x,t) = p₀ sin(kx − ωt).', equations: [{ eq: 'v = √(B / ρ)', label: 'Speed of sound', where: 'B = bulk modulus, ρ = density' }, { eq: 'β = 10 log₁₀(I / I₀)', label: 'Decibel level' }], calculated: ['Pressure variation', 'Speed in media', 'Intensity & loudness'], used: 'Music, sonar, ultrasound, acoustics, seismology, speech.', observe: 'Higher frequency = higher pitch; larger amplitude = louder. Sound needs a medium (no sound in vacuum).', why: 'Stiffer/denser media transmit disturbances faster; larger pressure swings carry more energy.', assumptions: ['Linear acoustic approximation', 'Uniform medium', 'Small pressure variations'], limitations: ['Shock waves are non-linear', 'Atmosphere is not uniform', 'Hearing is non-linear (log)'], controls: { 'Frequency (f)': { desc: 'Sets pitch.', unit: 'Hz' }, 'Amplitude (p₀)': { desc: 'Sets loudness (∝ p₀²).', unit: 'Pa' } }, viz: { 'Pressure pattern': 'Compressions and rarefactions travelling outward.' } },
  reflection: { means: 'Reflection is the bouncing of a wave off a boundary, with the angle of incidence equal to the angle of reflection.', explore: 'Law of reflection, specular vs diffuse, and surface properties.', what: 'A wave hitting a smooth surface bounces off so that the incoming and outgoing angles (measured from the normal) are equal.', name: 'Reflect — to bend back (Latin reflectere).', physical: 'Specular (mirror-smooth) gives a clear image; diffuse (rough) scatters in all directions.', quick: 'Angle in = angle out, measured from the perpendicular (normal). Smooth surfaces mirror; rough ones scatter.', physics: 'θ_i = θ_r, both measured from the surface normal. All in one plane.', math: 'Vector reflection flips the normal component of the direction.', equations: [{ eq: 'θ_i = θ_r', label: 'Law of reflection' }], calculated: ['Reflected ray direction', 'Image position'], used: 'Mirrors, periscopes, solar concentrators, radar, sonar.', observe: 'A perfectly smooth surface gives a sharp image; a rough one looks matte.', why: 'Smooth surfaces preserve the angle relationship; rough surfaces randomise it.', assumptions: ['Geometric optics (wavelength ≪ surface)', 'Smooth at the wavelength scale for specular'], limitations: ['Wave optics matters near edges & gratings', 'Real surfaces absorb some energy'], controls: { 'Surface roughness': { desc: 'Smooth = specular (mirror); rough = diffuse.', unit: '—' } }, viz: { 'Rays': 'Symmetric about the normal.' } },
  refraction: { means: 'Refraction is the bending of a wave when it passes into a medium where its speed changes.', explore: 'Snell\'s law, refractive index, total internal reflection.', what: 'Light slows in denser media and bends toward the normal; speeding up it bends away. The amount is set by the refractive indices.', name: 'Refract — to break/bend (Latin refringere).', physical: 'n = c/v. Snell: n₁ sinθ₁ = n₂ sinθ₂.', quick: 'Light bends when it changes speed at a boundary. Into glass it bends toward the normal; out, away. Past a critical angle it reflects entirely.', physics: 'Frequency stays constant across the boundary; wavelength changes as v = fλ changes.', math: 'Critical angle sinθ_c = n₂/n₁ (n₁ > n₂).', equations: [{ eq: 'n₁ sinθ₁ = n₂ sinθ₂', label: "Snell's law" }, { eq: 'n = c / v', label: 'Refractive index' }], calculated: ['Bend angle', 'Critical angle', 'Wavelength in media'], used: 'Lenses, prisms, fibre optics, mirages, rainbows, eye optics.', observe: 'Higher index contrast → more bending; beyond the critical angle, total internal reflection.', why: 'Slowing one side of the wavefront more than the other pivots the ray; the greater the speed change, the bigger the pivot.', assumptions: ['Geometric optics', 'Isotropic media', 'Smooth interface'], limitations: ['Real media disperse (n varies with λ)', 'Curved surfaces add aberrations'], controls: { 'Indices (n₁, n₂)': { desc: 'Speed ratio; bigger contrast = more bending.', unit: '—' }, 'Incident angle (θ₁)': { desc: 'Steeper entry bends more; past θ_c reflects totally.', unit: '°' } }, viz: { 'Ray diagram': 'Bends at the interface; normal is the reference.' } },
  snell: { means: "Snell's law gives the exact relationship between angles and refractive indices at an interface: n₁sinθ₁ = n₂sinθ₂.", explore: 'Index ratio, angles, critical angle, and total internal reflection.', what: 'The quantitative law of refraction — predicts exactly how much a ray bends.', name: 'Named after Willebrord Snellius (1621).', physical: 'Conservation of the tangential component of the wave vector across the boundary.', quick: 'The sine of the angle times the index is the same on both sides. Past the critical angle, no refraction — total reflection.', physics: 'n₁ sinθ₁ = n₂ sinθ₂; sinθ_c = n₂/n₁ when going to a less dense medium.', math: 'Derived from Fermat\'s principle (least time) or boundary phase matching.', equations: [{ eq: 'n₁ sinθ₁ = n₂ sinθ₂', label: "Snell's law" }, { eq: 'sinθ_c = n₂ / n₁', label: 'Critical angle' }], calculated: ['Refraction angle', 'Critical angle', 'TIR condition'], used: 'Fibre optics, lenses, prism dispersion, gemstone brilliance.', observe: 'Going to a denser medium bends toward normal; to a less dense, away; past θ_c, reflects.', why: 'The product n·sinθ is invariant; when it would exceed 1 (impossible), the wave reflects instead.', assumptions: ['Smooth interface', 'Isotropic media'], limitations: ['Dispersion: n depends on wavelength', 'Birefringent media have multiple indices'], controls: { 'n₁, n₂': { desc: 'Refractive indices; ratio sets bending.', unit: '—' }, 'θ₁': { desc: 'Incident angle from the normal.', unit: '°' } }, viz: { 'Refraction diagram': 'Ray bends; angle obeys n₁sinθ₁ = n₂sinθ₂.' } },
  lenses: { means: 'Lenses use refraction to focus or diverge light, forming images.', explore: 'Focal length, lensmaker\'s equation, real/virtual images, magnification.', what: 'A curved transparent shape bends parallel rays to a focal point (converging) or spreads them (diverging).', name: 'Lens — Latin lens, "lentil" (shape).', physical: '1/f = (n−1)(1/R₁ − 1/R₂). Thin-lens imaging: 1/f = 1/d_o + 1/d_i.', quick: 'A converging lens focuses parallel rays to a point (focal point); a diverging lens spreads them. Image position follows 1/f = 1/d_o + 1/d_i.', physics: 'Magnification M = −d_i/d_o. Real images form on a screen; virtual ones appear to come from behind the lens.', math: 'Sign conventions set real/virtual and upright/inverted.', equations: [{ eq: '1/f = 1/d_o + 1/d_i', label: 'Thin-lens equation' }, { eq: 'M = − d_i / d_o', label: 'Magnification' }, { eq: '1/f = (n−1)(1/R₁ − 1/R₂)', label: 'Lensmaker\'s equation' }], calculated: ['Image distance', 'Magnification', 'Image type (real/virtual)'], used: 'Glasses, cameras, microscopes, telescopes, projectors, eyes.', observe: 'Object beyond 2f → inverted smaller real image; inside f → upright enlarged virtual image (magnifier).', why: 'Moving the object changes d_o; the lens equation then sets where the image forms and how big.', assumptions: ['Thin lens', 'Paraxial rays (small angles)', 'Monochromatic'], limitations: ['Spherical & chromatic aberration', 'Thick lenses need more terms', 'Real lenses disperse colours'], controls: { 'Focal length (f)': { desc: 'Sets focusing power; shorter f = stronger lens.', unit: 'm' }, 'Object distance (d_o)': { desc: 'Where the object sits; determines image type.', unit: 'm' } }, viz: { 'Ray diagram': 'Three principal rays locate the image.' } },
  mirrors: { means: 'Curved mirrors form images by reflection (no refraction, so no chromatic aberration).', explore: 'Concave/convex, focal length, real/virtual images.', what: 'A concave mirror can focus light (converging); a convex mirror spreads it (diverging). Same 1/f = 1/d_o + 1/d_i as lenses.', name: 'Mirror — from Latin mirari, "to wonder at".', physical: 'Focal length f = R/2 for a spherical mirror.', quick: 'Concave mirrors focus light like converging lenses; convex mirrors give a wide upright view (car mirrors).', physics: 'Same imaging equation as lenses: 1/f = 1/d_o + 1/d_i, with f = R/2.', math: 'Magnification M = −d_i/d_o.', equations: [{ eq: '1/f = 1/d_o + 1/d_i', label: 'Mirror equation' }, { eq: 'f = R / 2', label: 'Focal length of spherical mirror' }], calculated: ['Image position', 'Magnification', 'Image type'], used: 'Telescopes, dental mirrors, car mirrors, solar furnaces, shaving mirrors.', observe: 'Concave: distant object forms a real inverted image at f. Convex: always upright, smaller, virtual.', why: 'Curvature focuses reflected rays; the radius sets the focal length.', assumptions: ['Paraxial rays', 'Spherical approximation'], limitations: ['Spherical aberration off-axis', 'Parabolic mirrors fix this for telescopes'], controls: { 'Radius (R)': { desc: 'Sets f = R/2; tighter curve = stronger mirror.', unit: 'm' }, 'Object distance': { desc: 'Determines image type and size.', unit: 'm' } }, viz: { 'Ray diagram': 'Reflected rays converge (concave) or diverge (convex).' } },
  lenscombo: { means: 'Lens combinations stack two or more lenses to build optical systems (telescopes, microscopes).', explore: 'System magnification, intermediate images, and compound optics.', what: 'The image of the first lens becomes the object for the second; multiply magnifications for the total.', name: 'Combination — multiple lenses in series.', physical: 'Telescope (objective + eyepiece), microscope (objective + eyepiece), camera zoom lenses.', quick: 'Two lenses in a row: the first makes an image that the second magnifies further. Total magnification = product of each.', physics: 'M_total = M₁ × M₂. Track intermediate image positions sequentially.', math: 'Apply the thin-lens equation twice, using the first image as the second object.', equations: [{ eq: 'M_total = M₁ × M₂', label: 'Compound magnification' }], calculated: ['Final image position', 'Total magnification'], used: 'Telescopes, microscopes, binoculars, camera lenses.', observe: 'Swap lens order or spacing and the system power changes dramatically.', why: 'Each lens reshapes the beam; the next lens acts on that reshaped beam, so effects compound.', assumptions: ['Thin lenses', 'Paraxial', 'Coaxial alignment'], limitations: ['Real systems have aberrations', 'Thick-lens and spacing matter'], controls: { 'Focal lengths (f₁, f₂)': { desc: 'Set individual powers; ratio sets telescope magnification.', unit: 'm' }, 'Separation': { desc: 'Distance between lenses; sets whether the system is telescope or microscope.', unit: 'm' } }, viz: { 'Ray trace': 'Shows intermediate and final images.' } },
  doubleslit: { means: "Young's double-slit experiment shows light producing an interference pattern — proof of its wave nature.", explore: 'Two coherent slits, fringe spacing, wavelength dependence.', what: 'Light through two narrow slits produces bright/dark bands on a screen — impossible if light were only particles.', name: 'Performed by Thomas Young (1801).', physical: 'Bright fringes where d sinθ = mλ; dark where d sinθ = (m+½)λ.', quick: 'Two slits make light + dark bands. Bright where paths differ by a whole wavelength; dark by a half. The classic proof light is a wave.', physics: 'Intensity I = I₀ cos²(πd sinθ/λ). Fringe spacing Δy = λL/d.', math: 'Single-slit envelope multiplies the double-slit pattern.', equations: [{ eq: 'd sinθ = m λ', label: 'Bright fringes' }, { eq: 'Δy = λ L / d', label: 'Fringe spacing' }], calculated: ['Fringe positions', 'Intensity pattern', 'Wavelength from fringes'], used: 'Measuring wavelengths, optical testing, holography, foundations of quantum mechanics.', observe: 'Red light makes wider fringes than blue; closer slits make wider fringes.', why: 'Wavelength sets the fringe scale; slit spacing sets how far apart the two "sources" are.', assumptions: ['Coherent monochromatic source', 'Far-field', 'Slits ≪ wavelength-wide'], limitations: ['Real slits have finite width (envelope)', 'Finite coherence washes fringes'], controls: { 'Wavelength (λ)': { desc: 'Sets fringe scale.', unit: 'nm' }, 'Slit separation (d)': { desc: 'Wider d = narrower fringes.', unit: 'μm' } }, viz: { 'Interference pattern': 'Bright/dark bands; spacing ∝ λ/d.' } },
  singleslit: { means: 'Single-slit diffraction is the spreading of light through one narrow aperture, producing a sinc-shaped pattern.', explore: 'Central maximum width, minima positions, and wavelength dependence.', what: 'Even one slit spreads light; the pattern has a wide central bright band flanked by weaker ones, with dark minima where a sinθ = mλ.', name: 'Diffraction — bending around obstacles (Latin diffringere, "to break apart").', physical: 'Each point across the slit acts as a source; their interference gives a sinc² intensity.', quick: 'One slit spreads light into a central bright band with dimmer side bands. Narrower slit = wider spread.', physics: 'I(θ) = I₀ sinc²(πa sinθ/λ). First minimum at a sinθ = λ.', math: 'The envelope modulates multi-slit patterns.', equations: [{ eq: 'a sinθ = m λ', label: 'Minima (m = ±1, ±2…)', where: 'a = slit width' }, { eq: 'I = I₀ sinc²(πa sinθ/λ)', label: 'Intensity' }], calculated: ['Central width', 'Minima positions', 'Wavelength'], used: 'Spectroscopy, telescope resolution (Rayleigh criterion), CD/DVD diffraction.', observe: 'Narrower slit = wider central maximum; longer wavelength = wider pattern.', why: 'A narrower aperture samples less of the wavefront, so diffraction spreads it more.', assumptions: ['Fraunhofer (far-field)', 'Monochromatic'], limitations: ['Near-field (Fresnel) differs', 'Real slits have edge effects'], controls: { 'Slit width (a)': { desc: 'Narrower a = wider diffraction.', unit: 'μm' }, 'Wavelength (λ)': { desc: 'Longer λ = wider pattern.', unit: 'nm' } }, viz: { 'Diffraction pattern': 'Wide central peak + weaker side lobes.' } },
  grating: { means: 'A diffraction grating uses many slits to produce sharp, widely separated bright fringes.', explore: 'Grating equation, order number, dispersion.', what: 'Many parallel slits sharpen the interference maxima into narrow bright lines, separating wavelengths precisely.', name: 'Grating — a grid of many slits.', physical: 'd sinθ = mλ; many slits make peaks sharp and bright.', quick: 'Thousands of slits turn blurry fringes into sharp spectral lines — the basis of spectroscopy.', physics: 'More slits N → narrower peaks (width ∝ 1/N), higher peak intensity.', math: 'The principal maxima follow the same equation as two slits but are far sharper.', equations: [{ eq: 'd sinθ = m λ', label: 'Grating equation', where: 'd = slit spacing, m = order' }], calculated: ['Diffraction angles', 'Spectral resolution', 'Wavelength separation'], used: 'Spectrometers, CD/DVD reading, pulse compression, astronomy.', observe: 'White light splits into a rainbow spectrum; higher orders spread more but dim.', why: 'More slits concentrate the constructive-interference directions into very narrow peaks.', assumptions: ['Uniform slit spacing', 'Far-field', 'Monochromatic per line'], limitations: ['Finite grating size broadens lines', 'Overlapping orders need filtering'], controls: { 'Slit spacing (d)': { desc: 'Smaller d = wider angular dispersion.', unit: 'lines/m' }, 'Number of slits (N)': { desc: 'More N = sharper, brighter peaks.', unit: '—' } }, viz: { 'Spectrum': 'Sharp bright lines at each order.' } },
  polarization: { means: 'Polarization describes the direction of a transverse wave\'s oscillation — for light, the direction of its electric field.', explore: 'Linear/circular polarization, Malus\'s law, polarizers.', what: 'Unpolarized light oscillates in all directions; a polarizer selects one. Two polarizers at angle θ transmit I = I₀ cos²θ.', name: 'Polar — relating to a directed axis.', physical: 'Malus\'s law: I = I₀ cos²θ. Polarization proves light is transverse.', quick: 'A polarizer picks one oscillation direction of light. Two crossed polarizers block all light; at 45° they pass half.', physics: 'Reflection and scattering naturally polarize light (sunglasses, sky).', math: 'Circular polarization = two equal linear components 90° out of phase.', equations: [{ eq: 'I = I₀ cos²θ', label: "Malus's law", where: 'θ between polarizer axes' }], calculated: ['Transmitted intensity', 'Polarization angle'], used: 'Sunglasses, LCDs, 3D glasses, stress analysis, optical communications.', observe: 'Crossed polarizers (90°) → dark; rotating the second brightens/darkens per cos²θ.', why: 'A polarizer projects the field onto its axis; the squared projection gives the transmitted intensity.', assumptions: ['Ideal polarizers', 'Monochromatic'], limitations: ['Real polarizers absorb some light', 'Birefringent materials split polarizations'], controls: { 'Angle (θ)': { desc: 'Between polarizer axes; sets transmitted intensity.', unit: '°' } }, viz: { 'Intensity vs angle': 'cos²θ curve.' } },
  michelson: { means: 'The Michelson interferometer splits light into two paths and recombines them, producing interference fringes.', explore: 'Path-length difference, fringe shifts, precision measurement.', what: 'A beam splitter sends light down two arms; mirrors return it; recombining produces fringes that shift when one arm moves by λ/2.', name: 'Invented by Albert Michelson (1880s).', physical: 'Each λ/2 arm shift moves one fringe — the basis of precision optical measurement.', quick: 'Split a beam, send it down two paths, recombine. Moving one mirror by half a wavelength shifts one fringe — exquisitely sensitive.', physics: 'Used to measure the speed of light and detect gravitational waves (LIGO is a Michelson).', math: 'N fringes shift = 2ΔL/λ.', equations: [{ eq: 'Δm = 2 ΔL / λ', label: 'Fringe shift per arm movement' }], calculated: ['Path difference', 'Fringe count', 'Tiny displacements'], used: 'LIGO gravitational-wave detection, optical metrology, calibration, Fourier spectroscopy.', observe: 'A tiny mirror shift moves the fringes; counting them measures the shift in wavelengths.', why: 'A path change of λ/2 changes the phase by 2π, moving one fringe.', assumptions: ['Coherent source', 'Stable optics'], limitations: ['Vibration sensitivity', 'Finite coherence length'], controls: { 'Arm length (L)': { desc: 'Changing it shifts fringes.', unit: 'm' } }, viz: { 'Fringes': 'Concentric or straight; shift with path difference.' } },
};

