// QUANTUM INFORMATION
const qinfo = {
  qubit: qubitBase,
  multiqubit: { ...qubitBase, means: 'A multi-qubit simulator models several qubits together, where entanglement becomes possible.', explore: 'Tensor-product states, entanglement, and multi-qubit gates.', what: 'N qubits live in a 2^N-dimensional space. Multi-qubit gates (CNOT, CZ) entangle qubits — a resource with no classical analogue.', name: 'Multi-qubit — 2 or more qubits; state space grows as 2^N.', physical: 'Entanglement is the signature: the joint state can\'t be factored into individual qubit states.', quick: 'Two or more qubits share a 2^N-dimensional space. Add a CNOT and they can entangle — their fates link in a way no classical bits can.', physics: 'State = tensor product of single-qubit spaces; entangling gates create non-factorable states.', math: 'Bell state (|00⟩+|11⟩)/√2 is maximally entangled.', equations: [{ eq: 'dim = 2^N', label: 'Hilbert space size' }, { eq: '|Φ⁺⟩ = (|00⟩ + |11⟩)/√2', label: 'Bell state' }], calculated: ['Joint state', 'Entanglement', 'Measurement correlations'], used: 'Quantum computing, quantum networking, quantum cryptography.', observe: 'Entangled qubits give correlated results even when measured far apart.', why: 'Entangling gates correlate qubits so the joint state can\'t be separated.', assumptions: ['Coherent qubits', 'Controllable couplings'], limitations: ['Decoherence grows with N', 'Crosstalk'], controls: { 'Qubit count (N)': { desc: 'Doubles the state space each time.', unit: '—' }, 'Entangling gate': { desc: 'CNOT/CZ create entanglement.', unit: '—' } }, viz: { 'Probability distribution': 'Over all 2^N bit strings.' } },
  gates: { ...qubitBase, means: 'Quantum gates are unitary operations that rotate qubit states — the quantum analogue of classical logic gates.', explore: 'X, Y, Z, H, S, T gates and their effect on the Bloch sphere.', what: 'Each gate is a unitary matrix (rotation). Single-qubit gates rotate one qubit; two-qubit gates entangle.', name: 'Gate — a reversible unitary operation (quantum gates are always reversible).', physical: 'X = bit flip; Z = phase flip; H = Hadamard (creates superposition); S, T = phase gates.', quick: 'Quantum gates rotate the qubit on the Bloch sphere. X flips it, H puts it in superposition, Z shifts its phase. All gates are reversible.', physics: 'Gates are SU(2) (single) or SU(2^N) (multi) rotations.', math: 'H = (|0⟩⟨0|+|0⟩⟨1|+|1⟩⟨0|−|1⟩⟨1|)/√2.', equations: [{ eq: 'H|0⟩ = (|0⟩+|1⟩)/√2', label: 'Hadamard creates superposition' }, { eq: 'X|0⟩ = |1⟩', label: 'Bit flip' }], calculated: ['Output state', 'Gate composition'], used: 'All quantum algorithms, quantum error correction.', observe: 'Composing gates rotates the Bloch vector along different axes.', why: 'Each gate is a rotation; composing them moves the state through the sphere.', assumptions: ['Unitary (lossless) gates'], limitations: ['Real gates are noisy and imperfect'], controls: { 'Gate type': { desc: 'Determines the rotation axis/angle.', unit: '—' } }, viz: { 'Bloch rotation': 'Vector moves on the sphere.' } },
  cnot: { ...qubitBase, means: 'CNOT, CZ, and SWAP are the fundamental two-qubit gates that create entanglement.', explore: 'Control–target structure, entanglement, and SWAP.', what: 'CNOT flips the target iff the control is |1⟩. CZ adds a phase when both are |1⟩. SWAP exchanges two qubits.', name: 'CNOT — controlled-NOT; CZ — controlled-Z; SWAP — exchange.', physical: 'CNOT + single-qubit gates form a universal gate set — any computation can be built from them.', quick: 'CNOT links two qubits: it flips the second only when the first is 1. This creates entanglement — the essential ingredient for quantum advantage.', physics: 'CNOT = |0⟩⟨0|⊗I + |1⟩⟨1|⊗X.', math: 'CNOT on (|0⟩+|1⟩)/√2 ⊗ |0⟩ gives the Bell state.', equations: [{ eq: 'CNOT = |0⟩⟨0|⊗I + |1⟩⟨1|⊗X', label: 'CNOT' }, { eq: 'SWAP|a,b⟩ = |b,a⟩', label: 'SWAP' }], calculated: ['Entangled output', 'Correlations'], used: 'Universal quantum computing, entanglement generation, error correction.', observe: 'CNOT on a superposition control creates entanglement; on a basis control it just flips.', why: 'The control-conditional action correlates the qubits, producing entanglement.', assumptions: ['Two-qubit coupling available'], limitations: ['Two-qubit gates are the noisiest in real hardware'], controls: { 'Control/Target': { desc: 'Which qubit controls, which is flipped.', unit: '—' } }, viz: { 'Before/after states': 'Show entanglement.' } },
  circuits: { ...qubitBase, means: 'A quantum circuit is a sequence of gates applied to qubits to perform a computation.', explore: 'Building, running, and measuring circuits.', what: 'Like a classical circuit but with quantum gates. Qubits flow left-to-right; gates act; measurement at the end gives probabilities.', name: 'Circuit — a gate sequence on wires (qubits).', physical: 'The circuit is a unitary; measurement samples from the output distribution.', quick: 'A quantum circuit is a recipe of gates on qubits. Run it and measure — you get bit strings with probabilities set by the final state.', physics: 'Apply gates as matrix products; the final state determines outcome probabilities.', math: 'Depth = number of gate layers; more depth = more noise.', equations: [{ eq: '|ψ_out⟩ = U_n … U_1 |ψ_in⟩', label: 'Circuit as unitary' }], calculated: ['Output state', 'Measurement distribution'], used: 'All quantum algorithms, error-correcting codes, quantum simulation.', observe: 'Adding gates changes the output distribution; entangling gates create correlations.', why: 'Each gate transforms the state; the sequence composes into a single unitary.', assumptions: ['Coherent qubits', 'Reliable gates'], limitations: ['Noise accumulates with depth', 'Real circuits need error correction'], controls: { 'Gate sequence': { desc: 'The algorithm.', unit: '—' }, 'Depth': { desc: 'Number of layers; affects noise.', unit: '—' } }, viz: { 'Circuit diagram': 'Gates on horizontal qubit wires.' } },
  teleport: { ...qubitBase, means: 'Quantum teleportation transfers an unknown qubit state from one place to another using entanglement + classical communication.', explore: 'Bell pair, Bell measurement, and classical correction.', what: 'You can\'t clone a qubit, but you can teleport its state: share a Bell pair, do a joint measurement, send 2 classical bits, and apply a correction.', name: 'Teleportation — moving state, not matter.', physical: 'Requires a pre-shared entangled pair and a classical channel; no faster-than-light signalling.', quick: 'Teleportation sends a qubit\'s state to a distant qubit using a shared entangled pair and two classical bits. The original is destroyed (no-cloning theorem).', physics: 'Bell measurement + conditional Pauli correction reconstructs the state at the receiver.', math: 'The classical bits tell which correction to apply.', equations: [{ eq: '|ψ⟩_A → |ψ⟩_B + 2 classical bits', label: 'Teleportation' }], calculated: ['Teleported state', 'Classical correction'], used: 'Quantum networking, quantum repeaters, distributed quantum computing.', observe: 'The receiver\'s qubit ends up in the original state only after the correction is applied.', why: 'Entanglement + classical info together let the receiver reconstruct the state exactly.', assumptions: ['Shared Bell pair', 'Classical channel', 'Perfect gates'], limitations: ['Real channels lose entanglement', 'Needs quantum repeaters for long distance'], controls: { 'Bell pair quality': { desc: 'Determines fidelity.', unit: '—' } }, viz: { 'Circuit': 'Bell measurement + correction.' } },
  superdense: { ...qubitBase, means: 'Superdense coding sends 2 classical bits using 1 qubit — the dual of teleportation.', explore: 'Entanglement-assisted communication.', what: 'With a shared Bell pair, sending one qubit transmits two classical bits — doubling capacity using entanglement.', name: 'Superdense — more than the classical limit.', physical: 'The sender encodes 2 bits by applying one of 4 Pauli operations to their half of the Bell pair.', quick: 'Share entanglement, then send a single qubit and the receiver gets 2 classical bits — beating the classical 1-bit limit using entanglement.', physics: 'Four Pauli operations on the sender\'s qubit create four distinguishable Bell states.', math: 'Requires pre-shared entanglement (a resource).', equations: [{ eq: '1 qubit + entanglement → 2 bits', label: 'Superdense coding' }], calculated: ['Encoded Bell state', 'Decoded bits'], used: 'Quantum communication, quantum networking theory.', observe: 'Without entanglement, 1 qubit carries at most 1 bit; with it, 2.', why: 'Entanglement expands the distinguishable states from 2 to 4.', assumptions: ['Shared Bell pair', 'Noiseless channel'], limitations: ['Entanglement is a consumed resource', 'Real channels are noisy'], controls: { 'Pauli choice': { desc: 'Which of 4 operations encodes the 2 bits.', unit: '—' } }, viz: { 'Bell-state decoding': '4 outcomes = 2 bits.' } },
  deutsch: { ...qubitBase, means: 'The Deutsch algorithm decides whether a function is constant or balanced using a single query — a quantum advantage.', explore: 'Oracle query, interference, and the constant/balanced distinction.', what: 'Classically you\'d need 2 queries to tell if a 1-bit function is constant (same output) or balanced (one 0, one 1). Deutsch does it in 1 query using superposition.', name: 'David Deutsch (1985) — the first quantum algorithm with an advantage.', physical: 'Uses superposition to query both inputs at once; interference cancels the wrong answer.', quick: 'The first quantum algorithm to beat classical: it tells if a function is constant or balanced with one query instead of two, using superposition and interference.', physics: 'Hadamard + oracle + Hadamard makes the answer appear in a single measurement.', math: 'Constant → |0⟩; balanced → |1⟩ (deterministically).', equations: [{ eq: '1 query vs 2 (classical)', label: 'Quantum advantage' }], calculated: ['Constant/balanced verdict'], used: 'Teaching quantum advantage, oracle-based algorithms.', observe: 'A single measurement gives the answer with certainty (ideal case).', why: 'Superposition queries both inputs simultaneously; interference concentrates the answer on one bit.', assumptions: ['Black-box oracle', 'Coherent qubits'], limitations: ['Limited practical use', 'Generalised by Deutsch–Jozsa'], controls: { 'Oracle type': { desc: 'Constant or balanced — the unknown.', unit: '—' } }, viz: { 'Output bit': '0 = constant, 1 = balanced.' } },
  dj: { ...qubitBase, means: 'Deutsch–Jozsa generalises Deutsch to n bits: decide constant vs balanced in one query.', explore: 'n-qubit superposition, parallelism, and deterministic advantage.', what: 'Classically you\'d need up to 2^(n−1)+1 queries in the worst case; quantum needs 1.', name: 'Deutsch & Jozsa (1992).', physical: 'Same interference trick, scaled to n qubits.', quick: 'A scaled-up Deutsch: with n qubits, one query decides constant vs balanced — exponentially better than the classical worst case.', physics: 'Hadamards create uniform superposition; the oracle imprints a phase; final Hadamards interfere to reveal the answer.', math: 'Constant → |00…0⟩; balanced → anything else.', equations: [{ eq: '1 query vs O(2^n) (classical worst case)', label: 'Exponential advantage' }], calculated: ['Constant/balanced verdict'], used: 'Teaching, foundations of quantum speed-up.', observe: 'Measure all-zeros → constant; otherwise balanced.', why: 'Uniform superposition + interference concentrates the global property into one measurement.', assumptions: ['Promise of constant or balanced', 'Oracle access'], limitations: ['Promise problem; limited practical use'], controls: { 'n': { desc: 'Number of input bits.', unit: '—' } }, viz: { 'Output register': 'All zeros or not.' } },
  bv: { ...qubitBase, means: 'Bernstein–Vazirani finds a hidden string s in one query, where classically you\'d need n.', explore: 'Hidden string, oracle, and linear advantage.', what: 'Given f(x) = s·x mod 2, find s. Quantum does it in 1 query; classical needs n.', name: 'Bernstein & Vazirani (1993).', physical: 'Uses phase kickback to read all bits of s at once.', quick: 'A hidden dot-product string s is recovered in a single quantum query — linear speed-up over classical.', physics: 'Phase kickback encodes each bit of s into a qubit.', math: 'Output = s directly.', equations: [{ eq: '1 query vs n (classical)', label: 'Linear advantage' }], calculated: ['Hidden string s'], used: 'Cryptography, oracle problems, teaching.', observe: 'The measurement yields s exactly.', why: 'Phase kickback transfers each bit of s to a separate qubit in one shot.', assumptions: ['Oracle f(x)=s·x', 'Coherent qubits'], limitations: ['Oracle problem; niche practical use'], controls: { 'n': { desc: 'String length.', unit: '—' } }, viz: { 'Output': 'The hidden string s.' } },
  grover: { ...qubitBase, means: "Grover's algorithm searches an unsorted database of N items in √N queries — a quadratic speed-up.", explore: 'Amplitude amplification, iterations, and the optimal count.', what: 'Find a marked item among N with ~√N oracle queries instead of N/2 classically.', name: 'Lov Grover (1996).', physical: 'Repeatedly amplifies the amplitude of the marked state via reflection about the mean.', quick: 'Grover finds a needle in a haystack of N in √N steps — a quadratic speed-up. Each iteration rotates the state closer to the target.', physics: 'Optimal iterations ≈ (π/4)√N; too many overshoot.', math: 'Amplitude amplification = reflection about |s⟩ then about |w⟩.', equations: [{ eq: '~√N queries vs N/2 (classical)', label: 'Quadratic speed-up' }, { eq: 'R ≈ (π/4)√N', label: 'Optimal iterations' }], calculated: ['Marked-item probability', 'Iteration count'], used: 'Unstructured search, optimisation, cryptography (e.g., AES key search).', observe: 'Probability of the marked item rises then oscillates; stop at the peak.', why: 'Each iteration rotates the state vector toward the target by a fixed angle; ~√N iterations reach it.', assumptions: ['Oracle marks the target', 'Known N'], limitations: ['Quadratic, not exponential', 'Needs the oracle'], controls: { 'N': { desc: 'Database size; iterations scale as √N.', unit: '—' }, 'Iterations': { desc: 'Too many overshoot.', unit: '—' } }, viz: { 'Probability distribution': 'Peak grows on the marked item.' } },
  qft: { ...qubitBase, means: 'The Quantum Fourier Transform computes the discrete Fourier transform exponentially faster than classical.', explore: 'Phase rotations, entanglement, and the circuit structure.', what: 'QFT maps a state to its frequency representation in O(n²) gates vs O(N log N) classically (N = 2^n).', name: 'Quantum Fourier Transform — the quantum DFT.', physical: 'Core subroutine of Shor\'s and many phase-estimation algorithms.', quick: 'QFT finds the "frequencies" in a quantum state in polynomial time — exponentially faster than the classical FFT — but you can only read out one frequency (measurement limit).', physics: 'Built from Hadamards and controlled phase rotations.', math: 'QFT|x⟩ = (1/√N) Σ e^(2πi xk/N)|k⟩.', equations: [{ eq: 'QFT|x⟩ = (1/√N) Σ_k e^(2πi xk/N) |k⟩', label: 'QFT definition' }], calculated: ['Frequency representation', 'Phase encoding'], used: 'Shor\'s algorithm, phase estimation, quantum simulation.', observe: 'A periodic state collapses to the frequency basis after QFT.', why: 'It encodes periodicities into the computational basis via phase.', assumptions: ['Coherent qubits', 'Precise rotations'], limitations: ['Can\'t read full output (only one sample)', 'Sensitive to noise'], controls: { 'n': { desc: 'Number of qubits; gates scale as n².', unit: '—' } }, viz: { 'Phase pattern': 'Rotations encode frequencies.' } },
  qpe: { ...qubitBase, means: 'Quantum Phase Estimation estimates the eigenphase of a unitary — a key subroutine for quantum chemistry and Shor.', explore: 'Controlled-U powers, inverse QFT, and precision.', what: 'Given U|u⟩ = e^(2πiφ)|u⟩, estimate φ to n bits of precision.', name: 'Phase estimation — finding the phase φ.', physical: 'Uses controlled-U^(2^k) and inverse QFT to read φ off the top register.', quick: 'QPE measures the hidden phase of a unitary operation — essential for finding energy levels (quantum chemistry) and for factoring (Shor).', physics: 'Higher powers of U accumulate more phase; inverse QFT converts it to bits.', math: 'Precision scales with the number of ancilla qubits.', equations: [{ eq: 'U|u⟩ = e^(2πiφ) |u⟩', label: 'Eigenphase' }], calculated: ['Phase φ', 'Energy (via U = e^(−iĤt))'], used: 'Quantum chemistry, Shor\'s algorithm, HHL linear solver.', observe: 'More ancilla qubits → more bits of φ.', why: 'Controlled powers encode φ into phases; inverse QFT reads them out.', assumptions: ['Controlled-U available', 'Eigenstate prep'], limitations: ['Needs many controlled powers', 'Sensitive to noise'], controls: { 'Ancilla qubits (n)': { desc: 'Sets precision (n bits).', unit: '—' } }, viz: { 'Phase readout': 'Binary fraction of φ.' } },
  shor: { ...qubitBase, means: "Shor's algorithm factors integers in polynomial time — the headline threat to RSA cryptography.", explore: 'Order finding, QPE, and classical post-processing.', what: 'Factoring N reduces to finding the period r of f(x) = a^x mod N. QPE finds r; classical gcd gives the factors.', name: 'Peter Shor (1994).', physical: 'Here demonstrated for N = 15 (factors 3 and 5) on a small quantum circuit.', quick: 'Shor factors numbers in polynomial time — breaking RSA. It turns factoring into period-finding, which QPE solves. This demo factors 15 = 3×5.', physics: 'Pick a, compute order r of a^x mod N, then gcd(a^(r/2) ± 1, N) gives factors.', math: 'The quantum part is order-finding; the rest is classical.', equations: [{ eq: 'gcd(a^(r/2) ± 1, N) → factors', label: 'Classical post-processing' }], calculated: ['Order r', 'Factors of N'], used: 'Cryptanalysis (the motivation for post-quantum crypto).', observe: 'For N=15, a=7, the order r=4 yields factors 3 and 5.', why: 'Period-finding via QPE reveals r; number theory turns r into factors.', assumptions: ['Many coherent qubits', 'Fault tolerance for large N'], limitations: ['Needs millions of qubits for real RSA keys', 'This demo is tiny (N=15)'], controls: { 'N': { desc: 'Number to factor.', unit: '—' }, 'Base (a)': { desc: 'Coprine to N.', unit: '—' } }, viz: { 'Period': 'Found via QPE.' } },
  entangle: { ...qubitBase, means: 'Entanglement is a quantum correlation with no classical equivalent — measuring one instantly fixes the other.', explore: 'Bell states, non-factorable states, and Bell inequalities.', what: 'Two qubits are entangled when their joint state can\'t be written as a product of individual states. Measuring one determines the other, even at a distance.', name: 'Entangle — to intertwine; here, quantum states that can\'t be separated.', physical: 'Bell states are maximally entangled; they violate Bell inequalities (no local hidden variables).', quick: 'Entanglement links two qubits so their results correlate perfectly — even across galaxies — in a way no classical theory with hidden variables can reproduce.', physics: 'Bell state (|00⟩+|11⟩)/√2: measure one, the other matches.', math: 'Entanglement entropy quantifies it; Bell inequalities bound classical correlations.', equations: [{ eq: '|Φ⁺⟩ = (|00⟩ + |11⟩)/√2', label: 'Bell state' }, { eq: 'Bell inequality violated', label: 'Non-classical correlations' }], calculated: ['Entanglement entropy', 'Correlations', 'Bell parameter'], used: 'Quantum computing, cryptography (QKD), teleportation, superdense coding.', observe: 'Entangled qubits give correlated outcomes; separated measurements still match.', why: 'A non-factorable joint state means the qubits share one description — measuring one collapses both.', assumptions: ['Shared entangled pair', 'Space-like separated measurements'], limitations: ['Decoherence destroys entanglement', 'No faster-than-light signalling'], controls: { 'Entangling gate': { desc: 'CNOT/CZ create entanglement from superposition.', unit: '—' } }, viz: { 'Joint distribution': 'Perfectly correlated (or anti-correlated).' } },
  density: { ...qubitBase, means: 'Density matrices describe quantum states including mixed (noisy) ones; quantum channels describe their evolution.', explore: 'ρ, purity, Kraus operators, and noise channels.', what: 'A pure state uses |ψ⟩; a mixed state (e.g., from noise) needs the density matrix ρ = Σ p_i |ψ_i⟩⟨ψ_i|. Channels map ρ → ρ\'.', name: 'Density matrix — the general state descriptor; channel — the general evolution.', physical: 'Purity Tr(ρ²) = 1 for pure, < 1 for mixed. Channels model noise (dephasing, depolarising, amplitude damping).', quick: 'When noise blurs a quantum state, a single |ψ⟩ isn\'t enough — use the density matrix ρ. Channels describe how noise changes ρ.', physics: 'Kraus: ρ → Σ K_i ρ K_i†, with Σ K_i†K_i = I.', math: 'Von Neumann entropy S = −Tr(ρ log ρ) measures mixedness.', equations: [{ eq: 'ρ = Σ p_i |ψ_i⟩⟨ψ_i|', label: 'Density matrix' }, { eq: 'ρ → Σ K_i ρ K_i†', label: 'Kraus channel' }], calculated: ['Purity', 'Entropy', 'Channel output'], used: 'Open quantum systems, noise modelling, quantum error correction.', observe: 'Depolarising noise shrinks the Bloch vector toward the centre; dephasing shrinks it along z.', why: 'Noise turns pure states into mixtures; the density matrix tracks the resulting uncertainty.', assumptions: ['Markovian noise', 'Known Kraus operators'], limitations: ['Non-Markovian noise needs memory', 'Real channels are approximate'], controls: { 'Noise strength (p)': { desc: 'How much the channel mixes the state.', unit: '—' } }, viz: { 'Bloch ball': 'Pure states on surface; mixed inside.' } },
  vonNeumann: { ...qubitBase, means: 'Von Neumann entropy S = −Tr(ρ log ρ) measures the mixedness of a quantum state.', explore: 'Pure vs mixed, entanglement entropy, and the link to information.', what: 'S = 0 for pure states, maximal for maximally mixed. For a subsystem, it equals the entanglement entropy.', name: 'John von Neumann.', physical: 'Quantum analogue of Shannon entropy; quantifies uncertainty in the state.', quick: 'Von Neumann entropy measures how "mixed" a quantum state is: 0 for pure, max for a completely random state. For part of a system, it measures entanglement.', physics: 'S = −Tr(ρ log₂ ρ); ranges [0, log₂ d].', math: 'For a Bell state, each qubit has S = 1 bit of entanglement.', equations: [{ eq: 'S = −Tr(ρ log ρ)', label: 'Von Neumann entropy' }], calculated: ['State mixedness', 'Entanglement entropy'], used: 'Quantum information, entanglement theory, thermodynamics.', observe: 'Pure states have S=0; depolarising noise raises S.', why: 'More mixing = more uncertainty = higher entropy.', assumptions: ['Known ρ'], limitations: ['Hard to measure directly', 'Basis-dependent for subsystems'], controls: { 'Mixedness': { desc: 'Set by the channel/noise.', unit: '—' } }, viz: { 'Entropy': '0 (pure) to log₂d (max mixed).' } },
  fidelity: { ...qubitBase, means: 'Quantum fidelity measures how close two states are; trace distance measures how distinguishable.', explore: 'F(ρ,σ), D(ρ,σ), and their operational meanings.', what: 'Fidelity F = 1 for identical states, 0 for orthogonal. Trace distance D = 0 for identical, 1 for perfectly distinguishable.', name: 'Fidelity — closeness; trace distance — distinguishability.', physical: 'D bounds the maximum success advantage in telling the states apart.', quick: 'Fidelity asks "how alike?"; trace distance asks "how tellable apart?" Both quantify the difference between two quantum states.', physics: 'F(ρ,σ) = (Tr√(√ρ σ √ρ))²; D = ½Tr|ρ−σ|.', math: 'Related: 1 − F ≤ D ≤ √(1 − F).', equations: [{ eq: 'F(ρ,σ) = (Tr√(√ρ σ √ρ))²', label: 'Fidelity' }, { eq: 'D(ρ,σ) = ½ Tr|ρ−σ|', label: 'Trace distance' }], calculated: ['State closeness', 'Distinguishability'], used: 'Quantum error correction (benchmarking), state tomography, cryptography.', observe: 'Noise reduces fidelity with the target; trace distance grows.', why: 'Fidelity and distance are dual views of how much two states differ.', assumptions: ['Known states'], limitations: ['Hard to estimate experimentally without tomography'], controls: { 'Noise': { desc: 'Lowers fidelity, raises distance.', unit: '—' } }, viz: { 'Bloch vectors': 'Closer = higher fidelity.' } },
  bell: { ...qubitBase, means: 'Bell-state analysis studies the four maximally entangled two-qubit states.', explore: 'The four Bell states, their correlations, and uses.', what: '|Φ±⟩ = (|00⟩±|11⟩)/√2, |Ψ±⟩ = (|01⟩±|10⟩)/√2. Each is maximally entangled; together they form a basis.', name: 'Bell states — after John Bell (inequalities).', physical: 'Bell states give perfect (anti)correlations in any measurement basis.', quick: 'The four Bell states are the "gold standard" of entanglement — perfectly correlated two-qubit states used in teleportation, superdense coding, and QKD.', physics: 'They form a complete orthonormal basis of the two-qubit space.', math: 'Bell measurement distinguishes them (in some bases).', equations: [{ eq: '|Φ⁺⟩ = (|00⟩+|11⟩)/√2', label: 'Bell state' }], calculated: ['Correlations', 'Entanglement'], used: 'Teleportation, superdense coding, entanglement swapping, QKD.', observe: 'Each Bell state gives distinct (anti)correlations in x and z bases.', why: 'Maximal entanglement gives maximal correlations — the resource for quantum protocols.', assumptions: ['Two qubits', 'Entangling capability'], limitations: ['Real Bell pairs are noisy', 'Full Bell measurement needs extra resources'], controls: { 'Bell state': { desc: 'Which of the four.', unit: '—' } }, viz: { 'Correlation table': 'Perfect (anti)correlations.' } },
  tomo: { ...qubitBase, means: 'Quantum tomography reconstructs an unknown quantum state from many measurements in different bases.', explore: 'Measurement bases, reconstruction, and the exponential cost.', what: 'Measure in x, y, z bases many times; from the statistics, reconstruct the density matrix ρ.', name: 'Tomography — from Greek, "slice writing"; reconstructing from projections.', physical: 'Needs exponentially many measurements for n qubits (3^n settings).', quick: 'You can\'t read a quantum state in one shot. Tomography measures it in many bases, many times, and statistically reconstructs ρ — expensive but complete.', physics: '⟨X⟩, ⟨Y⟩, ⟨Z⟩ give the Bloch vector for one qubit; more bases for more qubits.', math: 'Maximum-likelihood estimation handles noisy, incomplete data.', equations: [{ eq: 'ρ = ½(I + ⟨X⟩X + ⟨Y⟩Y + ⟨Z⟩Z)', label: 'Single-qubit reconstruction' }], calculated: ['Density matrix', 'Purity', 'Fidelity'], used: 'State characterisation, benchmarking, verifying entanglement.', observe: 'More samples → more accurate ρ; more qubits → exponentially more settings.', why: 'Each basis reveals one component; combining them fully specifies the state.', assumptions: ['Many identical copies', 'Known measurement bases'], limitations: ['Exponential cost in qubit number', 'Sensitive to noise'], controls: { 'Bases': { desc: 'Which measurement settings.', unit: '—' }, 'Samples': { desc: 'More = better stats.', unit: '—' } }, viz: { 'Reconstructed ρ': 'Bloch vector or matrix.' } },
};

