// COMPUTATIONAL PHYSICS
const comp = {
  numint: { ...numericsBase, means: 'Numerical integration approximates a definite integral when no analytic antiderivative exists.', explore: 'Simpson, Gauss, and error convergence.', what: 'Approximate ∫f dx by sampling f at points and weighting them. Simpson fits parabolas; Gauss chooses optimal points.', name: 'Quadrature — computing an integral numerically.', physical: 'Used whenever an integral has no closed form (most real problems).', quick: 'When you can\'t integrate by hand, sample the function at points and weight them. Simpson (parabolas) and Gauss (optimal points) are accurate and fast.', physics: 'Simpson: O(Δx⁴) error. Gauss: exponential convergence for smooth f.', math: 'Composite Simpson: (Δx/3)[f₀ + 4f₁ + 2f₂ + … + f_n].', equations: [{ eq: '∫f dx ≈ Σ w_i f(x_i)', label: 'Quadrature rule' }], calculated: ['Integral value', 'Error vs step'], used: 'Physics, engineering, statistics, finance.', observe: 'Halving the step shrinks Simpson error by 16×.', why: 'Higher-order rules fit the function better between samples.', assumptions: ['Smooth f', 'Known interval'], limitations: ['Singularities need special handling', 'High dimensions need Monte Carlo'], controls: { 'Step (Δx)': { desc: 'Smaller = more accurate.', unit: '—' }, 'Method': { desc: 'Simpson vs Gauss.', unit: '—' } }, viz: { 'Convergence': 'Log error vs log step.' } },
  numdiff: { ...numericsBase, means: 'Numerical differentiation estimates derivatives from function values.', explore: 'Forward, central, and higher-order differences; round-off trade-off.', what: 'Approximate f\'(x) from f(x±h). Central differences are more accurate; too-small h amplifies round-off.', name: 'Finite difference — derivative from nearby values.', physical: 'Used when you can\'t differentiate analytically (e.g., measured data).', quick: 'Estimate a slope from nearby points. Central differences are best; but if points are too close, round-off ruins it.', physics: 'Forward: (f(x+h)−f(x))/h, O(h). Central: (f(x+h)−f(x−h))/2h, O(h²).', math: 'Optimal h balances truncation vs round-off.', equations: [{ eq: "f'(x) ≈ (f(x+h) − f(x−h)) / 2h", label: 'Central difference' }], calculated: ['Derivative estimate', 'Error'], used: 'Solving ODEs/PDEs, data analysis, optimisation.', observe: 'Central is far more accurate than forward; too-small h raises round-off error.', why: 'Wider spacing truncates more; narrower spacing amplifies round-off — there\'s an optimum.', assumptions: ['Smooth f', 'Floating-point arithmetic'], limitations: ['Noisy data gives poor derivatives', 'Optimal h is problem-dependent'], controls: { 'Spacing (h)': { desc: 'Balances truncation vs round-off.', unit: '—' } }, viz: { 'Error vs h': 'U-shape (truncation + round-off).' } },
  rootfind: { ...numericsBase, means: 'Root finding locates where a function equals zero — essential for solving equations.', explore: 'Bisection, Newton, secant methods and their convergence.', what: 'Bisection brackets and halves (slow, safe). Newton uses the derivative (fast, may fail). Secant approximates the derivative.', name: 'Root — where f(x) = 0.', physical: 'Used to solve f(x)=0 when no formula exists (most real equations).', quick: 'Find where a function crosses zero. Bisection is foolproof but slow; Newton is fast but needs the derivative and can diverge.', physics: 'Newton: x_{n+1} = x_n − f/f\'. Quadratic convergence near a simple root.', math: 'Bisection needs a sign change; Newton needs f\' and a good start.', equations: [{ eq: 'x_{n+1} = x_n − f(x_n)/f\'(x_n)', label: "Newton's method" }], calculated: ['Root location', 'Iterations to converge'], used: 'Solving nonlinear equations, optimisation, circuit bias points.', observe: 'Newton converges quadratically near the root; diverges if f\'≈0 or start is poor.', why: 'Newton follows the tangent; bisection guarantees progress by bracketing.', assumptions: ['Continuous f', 'Good initial guess (Newton)'], limitations: ['Newton can diverge', 'Bisection is slow', 'Multiple roots need care'], controls: { 'Initial guess': { desc: 'Critical for Newton.', unit: '—' }, 'Tolerance': { desc: 'When to stop.', unit: '—' } }, viz: { 'Iteration path': 'Converges (or diverges) to the root.' } },
  ode: { ...numericsBase, means: 'ODE solvers integrate ordinary differential equations step-by-step.', explore: 'Euler, RK2, RK4, adaptive RK45, and accuracy vs cost.', what: 'Given ẏ = f(y,t), march forward in time. Euler is simplest (O(h)); RK4 is the workhorse (O(h⁴)); adaptive RK45 adjusts step size.', name: 'ODE — ordinary differential equation (one independent variable).', physical: 'Most physics is ODEs (motion, circuits, decay). The solver choice sets accuracy and stability.', quick: 'Time-step a differential equation. Euler is crude; RK4 is the standard accurate choice; adaptive methods shrink steps where needed.', physics: 'RK4 = four slope estimates per step, weighted for O(h⁴) accuracy.', math: 'Adaptive: estimate error, halve/double step accordingly.', equations: [{ eq: 'y_{n+1} = y_n + (k1 + 2k2 + 2k3 + k4)/6', label: 'RK4 step' }], calculated: ['Solution trajectory', 'Error', 'Step-size history'], used: 'All dynamics, orbits, circuits, chemical kinetics.', observe: 'Euler drifts; RK4 tracks the true solution closely; adaptive saves effort.', why: 'Higher-order methods use more slope samples to better follow the curve.', assumptions: ['Smooth f', 'Stable step size'], limitations: ['Stiff systems need implicit methods', 'Energy drift in long runs'], controls: { 'Step (Δt)': { desc: 'Smaller = more accurate, slower.', unit: '—' }, 'Method': { desc: 'Euler/RK4/adaptive.', unit: '—' } }, viz: { 'Solution vs exact': 'Shows accuracy.' } },
  pde: { ...numericsBase, means: 'PDE solvers handle equations with multiple independent variables (space + time).', explore: 'Finite differences, split-step Fourier, and stability.', what: 'Discretise space and time (or use spectral methods). The Schrödinger solver here uses split-step Fourier for accuracy.', name: 'PDE — partial differential equation (multiple variables).', physical: 'Waves, heat, fluids, quantum — all PDEs.', quick: 'PDEs describe fields in space and time. You discretise both, or use spectral (Fourier) methods for accuracy and stability.', physics: 'CFL condition: Δt ≤ C Δx for explicit methods.', math: 'Split-step alternates kinetic (spectral) and potential (real-space) evolution.', equations: [{ eq: '∂u/∂t = L u', label: 'Generic PDE' }, { eq: 'Δt ≤ C Δx²', label: 'Stability (diffusion)' }], calculated: ['Field evolution', 'Stability'], used: 'Fluids, heat, electromagnetism, quantum, finance.', observe: 'Too-large time step → instability (blow-up).', why: 'Stability limits how fast you can step; spectral methods ease this.', assumptions: ['Smooth fields', 'Stable scheme'], limitations: ['High cost in 3D', 'Boundaries need care'], controls: { 'Grid (Δx, Δt)': { desc: 'Must satisfy stability.', unit: '—' } }, viz: { 'Field evolution': 'Over space and time.' } },
  eig: { ...numericsBase, means: 'Eigenvalue solvers find the characteristic values and vectors of a matrix — central to quantum and vibration problems.', explore: 'Jacobi, power iteration, and QR.', what: 'Given A, find λ and v with Av = λv. Quantum energies, vibration modes, and stability all reduce to eigenproblems.', name: 'Eigen — "characteristic" values of a matrix.', physical: 'The Schrödinger equation is an eigenvalue problem; structural vibrations are too.', quick: 'Eigenvalues are the "natural numbers" of a matrix — the frequencies it vibrates at, the energies a quantum system has. Solvers find them numerically.', physics: 'Jacobi rotates to diagonalise; power iteration finds the largest.', math: 'QR algorithm is the general workhorse.', equations: [{ eq: 'A v = λ v', label: 'Eigenvalue equation' }], calculated: ['Eigenvalues', 'Eigenvectors'], used: 'Quantum mechanics, vibrations, PCA, stability, Google PageRank.', observe: 'Symmetric matrices have real eigenvalues; degeneracies occur with symmetry.', why: 'Eigenvalues reveal the intrinsic scales of the system.', assumptions: ['Diagonalisable matrix'], limitations: ['Large matrices are expensive', 'Degeneracies need special handling'], controls: { 'Matrix size (n)': { desc: 'Cost scales as n³.', unit: '—' } }, viz: { 'Spectrum': 'Eigenvalues on a number line.' } },
  matrix: { ...numericsBase, means: 'A matrix laboratory performs linear algebra — solving systems, inverses, decompositions.', explore: 'LU, QR, SVD, and solving Ax = b.', what: 'Linear algebra underlies almost all numerical physics. LU solves Ax=b; SVD reveals structure (rank, conditioning).', name: 'Matrix — a 2D array; the workhorse of computation.', physical: 'Quantum states are vectors; operators are matrices; measurements are projections.', quick: 'Most physics computation is linear algebra: solve Ax = b, decompose matrices (LU, QR, SVD), find eigenvalues.', physics: 'SVD: A = UΣV†; reveals rank and conditioning.', math: 'Condition number = σ_max/σ_min sets numerical sensitivity.', equations: [{ eq: 'A x = b', label: 'Linear system' }, { eq: 'A = U Σ V†', label: 'SVD' }], calculated: ['Solutions', 'Decompositions', 'Conditioning'], used: 'Everything numerical — physics, ML, graphics, engineering.', observe: 'Ill-conditioned matrices lose precision; SVD exposes it.', why: 'Decompositions turn hard problems into stable sequences of easy ones.', assumptions: ['Well-conditioned problem'], limitations: ['Ill-conditioning amplifies round-off', 'Large matrices are expensive'], controls: { 'Size (n)': { desc: 'Cost scales as n³.', unit: '—' } }, viz: { 'Singular values': 'Reveal rank and conditioning.' } },
  fourier: { ...numericsBase, means: 'The Fourier transform decomposes a signal into its frequency components.', explore: 'Continuous FT, frequency content, and spectra.', what: 'Any signal can be expressed as a sum of sinusoids. The FT shows how much of each frequency is present.', name: 'Joseph Fourier (1822) — heat-conduction analysis.', physical: 'Converts between time/space and frequency domains; the two views are equivalent.', quick: 'The Fourier transform reveals the frequencies inside a signal — turning a wiggly waveform into a spectrum of pure tones.', physics: 'F(ω) = ∫ f(t) e^(−iωt) dt.', math: 'Parseval: energy is conserved between domains.', equations: [{ eq: 'F(ω) = ∫ f(t) e^(−iωt) dt', label: 'Fourier transform' }], calculated: ['Frequency spectrum', 'Power', 'Phase'], used: 'Signal processing, spectroscopy, imaging, quantum, communications.', observe: 'A pure sinusoid → a single spike; a pulse → a broad spectrum.', why: 'Different frequencies contribute differently; the FT separates them.', assumptions: ['Integrable signal'], limitations: ['Time-frequency trade-off (uncertainty)', 'Discrete data needs DFT/FFT'], controls: { 'Signal': { desc: 'What you transform.', unit: '—' } }, viz: { 'Spectrum': 'Frequency content.' } },
  fft: { ...numericsBase, means: 'The Fast Fourier Transform computes the discrete Fourier transform in O(N log N) instead of O(N²).', explore: 'Radix-2 Cooley–Tukey, butterfly, and speed-up.', what: 'A clever algorithm that factors the DFT into smaller transforms, slashing the cost.', name: 'Cooley–Tukey (1965) — the algorithm that made digital signal processing practical.', physical: 'Used everywhere signals are analysed — audio, images, spectroscopy, quantum.', quick: 'The FFT is the algorithm that made the digital revolution possible: it computes the frequency spectrum of N samples in N log N steps, not N².', physics: 'Splits even/odd samples recursively (radix-2).', math: 'Speed-up ≈ N/log N over the direct DFT.', equations: [{ eq: 'O(N log N) vs O(N²)', label: 'FFT speed-up' }], calculated: ['Frequency spectrum', 'Power spectrum'], used: 'Audio, image compression (JPEG), MRI, spectroscopy, quantum simulation.', observe: 'Doubling N adds only one more layer of work.', why: 'Recursion splits the problem into halves, each cheaper to solve.', assumptions: ['N a power of 2 (radix-2)'], limitations: ['Needs padded N for non-power-of-2', 'Round-off in deep recursions'], controls: { 'N': { desc: 'Number of samples.', unit: '—' } }, viz: { 'Power spectrum': 'Frequency vs amplitude.' } },
  mcmc: { ...numericsBase, means: 'Markov Chain Monte Carlo samples from probability distributions by random walking — essential for statistical physics.', explore: 'Metropolis, detailed balance, and convergence.', what: 'Build a random walk whose equilibrium distribution is your target; sample it to estimate averages.', name: 'MCMC — Markov chain (memoryless) + Monte Carlo (random).', physical: 'The Ising model and many-body systems are sampled this way.', quick: 'MCMC explores a probability landscape by random walking, settling into the target distribution. It\'s how we compute averages for systems with astronomically many states.', physics: 'Metropolis: propose, accept with min(1, e^(−ΔE/kT)); satisfies detailed balance.', math: 'Converges to the Boltzmann distribution; error ∝ 1/√N.', equations: [{ eq: 'P(accept) = min(1, e^(−ΔE/kT))', label: 'Metropolis rule' }], calculated: ['Thermodynamic averages', 'Free energy', 'Phase transitions'], used: 'Statistical mechanics, Bayesian inference, quantum chemistry.', observe: 'Near critical points, convergence slows (critical slowing down).', why: 'Detailed balance ensures the walk equilibrates to the target distribution.', assumptions: ['Ergodic chain', 'Detailed balance'], limitations: ['Slow convergence', 'Correlated samples'], controls: { 'Temperature (T)': { desc: 'Sets the target distribution.', unit: 'K' }, 'Steps (N)': { desc: 'More = less noise.', unit: '—' } }, viz: { 'Sample histogram': 'Converges to target.' } },
  fdm: { ...numericsBase, means: 'The Finite Difference Method approximates derivatives by differences on a grid — the simplest PDE solver.', explore: 'Grids, stencils, and stability.', what: 'Replace derivatives with differences between neighbouring grid points. Easy to implement; stability limits the step.', name: 'Finite difference — derivative ≈ difference / spacing.', physical: 'Used for the wave equation here (FDTD).', quick: 'FDM turns a PDE into algebra on a grid: replace d/dx with (f(x+h)−f(x))/h. Simple, but stability constrains the step size.', physics: 'CFL condition links Δt and Δx.', math: 'Stencil = the pattern of neighbours used.', equations: [{ eq: '∂f/∂x ≈ (f_{i+1} − f_i)/Δx', label: 'Forward difference' }], calculated: ['Field on a grid', 'Stability'], used: 'Waves, heat, fluids, electromagnetism.', observe: 'Too-large steps → instability; finer grids → more accurate but slower.', why: 'Local differences approximate the continuum derivative.', assumptions: ['Structured grid', 'Smooth solution'], limitations: ['Complex geometries are hard', 'Stability limits step size'], controls: { 'Grid (Δx, Δt)': { desc: 'Must satisfy stability.', unit: '—' } }, viz: { 'Grid field': 'Values at grid points.' } },
  fem: { ...numericsBase, means: 'The Finite Element Method solves PDEs on complex geometries by dividing the domain into elements.', explore: 'Mesh, basis functions, and weak form.', what: 'Split the domain into small elements, approximate the solution with simple basis functions in each, and solve the resulting system.', name: 'Finite element — piecewise approximation over a mesh.', physical: 'The standard for engineering simulation (stress, heat, fluids) on real shapes.', quick: 'FEM handles complex shapes by tiling them with small elements and solving locally. It\'s the backbone of engineering simulation.', physics: 'Weak form + basis functions → linear system.', math: 'Converges as the mesh refines.', equations: [{ eq: '∫ (∇v·∇u) = ∫ v f', label: 'Weak form (Poisson)' }], calculated: ['Field over a mesh', 'Stress/temperature/flow'], used: 'Structural engineering, aerodynamics, heat transfer, electromagnetism.', observe: 'Finer mesh → more accurate; adaptive refinement concentrates elements where needed.', why: 'Local basis functions approximate the solution well on any geometry.', assumptions: ['Valid mesh', 'Smooth enough solution'], limitations: ['Mesh generation is hard', 'Costly for 3D'], controls: { 'Mesh size': { desc: 'Finer = more accurate.', unit: '—' } }, viz: { 'Mesh + solution': 'Coloured field over elements.' } },
  numlinalg: { ...numericsBase, means: 'Numerical linear algebra solves matrix problems on computers — the core of scientific computing.', explore: 'LU, QR, SVD, conditioning, and iterative methods.', what: 'Direct (LU, QR, SVD) and iterative (CG, GMRES) solvers for large linear systems and eigenproblems.', name: 'Numerical linear algebra — matrix computation in floating point.', physical: 'Underlies nearly every simulation.', quick: 'Almost all scientific computing reduces to linear algebra. Direct solvers (LU, QR, SVD) are exact-ish; iterative ones handle huge sparse systems.', physics: 'Sparse matrices (mostly zeros) enable huge simulations.', math: 'Conditioning and sparsity determine method choice.', equations: [{ eq: 'A x = b', label: 'The core problem' }], calculated: ['Solutions', 'Decompositions', 'Eigenvalues'], used: 'All computational physics, ML, graphics.', observe: 'Sparse iterative solvers scale to billions of unknowns.', why: 'Sparsity and structure make huge problems tractable.', assumptions: ['Well-posed', 'Reasonable conditioning'], limitations: ['Ill-conditioning', 'Memory for huge dense matrices'], controls: { 'Sparsity': { desc: 'Enables large problems.', unit: '—' } }, viz: { 'Sparsity pattern': 'Nonzero structure.' } },
  erranalysis: { ...numericsBase, means: 'Error and convergence analysis quantifies how accurate a numerical result is.', explore: 'Truncation, round-off, and convergence rates.', what: 'Every numerical result has error: truncation (from the method) and round-off (from finite precision). Convergence analysis shows how error shrinks with effort.', name: 'Truncation — method error; round-off — finite-precision error.', physical: 'Without error analysis, a number is just a number.', quick: 'A computed answer is only as good as its error. Halve the step and watch the error — the rate reveals the method\'s order.', physics: 'Order p: error ∝ h^p. Round-off grows as h shrinks.', math: 'Richardson extrapolation combines results to cancel error.', equations: [{ eq: 'error ≈ C h^p', label: 'Order-p convergence' }], calculated: ['Error estimates', 'Convergence order'], used: 'Validating all numerical methods.', observe: 'Log-log plot of error vs step gives the slope = order p.', why: 'Knowing the order lets you predict and control accuracy.', assumptions: ['Smooth problem', 'Sufficiently fine steps'], limitations: ['Round-off floor limits gains', 'Singularities break rates'], controls: { 'Step (h)': { desc: 'Sweep to measure order.', unit: '—' } }, viz: { 'Log error vs log h': 'Slope = order p.' } },
  deviz: { ...numericsBase, means: 'A differential equation visualiser shows how solutions evolve and how error grows.', explore: 'Solution curves, phase portraits, and error.', what: 'Plot the solution of an ODE, its trajectory in phase space, and the numerical error vs the exact solution.', name: 'Visualiser — graphical exploration of ODE behaviour.', physical: 'Reveals stability, fixed points, and chaos.', quick: 'See the solution curve, its phase portrait, and how far the numerical answer drifts from the truth.', physics: 'Phase portraits reveal fixed points and limit cycles.', math: 'Error growth distinguishes stable from unstable systems.', equations: [{ eq: 'ẏ = f(y,t)', label: 'ODE' }], calculated: ['Solution', 'Phase portrait', 'Error'], used: 'Teaching, dynamical systems, control.', observe: 'Stable systems\' errors stay bounded; unstable ones grow.', why: 'Visualisation reveals qualitative behaviour that numbers alone hide.', assumptions: ['2D phase space for plotting'], limitations: ['Higher dimensions need projection'], controls: { 'Initial condition': { desc: 'Where the trajectory starts.', unit: '—' } }, viz: { 'Phase portrait': 'Trajectories in (y, ẏ) space.' } },
  ca: { ...numericsBase, means: 'Cellular automata are grids of cells that update by simple local rules — emergent complexity from simple rules.', explore: 'Rules, patterns, and emergence.', what: 'Each cell\'s next state depends on its neighbours via a fixed rule. Simple rules can produce complex, even life-like, patterns.', name: 'Cellular automaton — a grid of state machines.', physical: 'Conway\'s Game of Life, traffic models, lattice gases.', quick: 'A grid where each cell follows a tiny rule based on its neighbours. From these simple rules, stunning complexity emerges — a model of how nature computes.', physics: 'Rule 30 is pseudo-random; Game of Life is Turing-complete.', math: 'Wolfram\'s classification of 1D rules.', equations: [{ eq: 'cell_{t+1} = rule(neighbours_t)', label: 'CA update' }], calculated: ['Grid evolution', 'Pattern statistics'], used: 'Modelling biology, traffic, cryptography, physics.', observe: 'Some rules freeze, some oscillate, some produce endless complexity.', why: 'Local rules + many cells = emergent global behaviour.', assumptions: ['Discrete states', 'Local rules'], limitations: ['Hard to analyse mathematically', 'Not all physics is discrete'], controls: { 'Rule': { desc: 'The update function.', unit: '—' } }, viz: { 'Grid evolution': 'Patterns over time.' } },
  optim: { ...numericsBase, means: 'Numerical optimisation finds the minimum or maximum of a function — central to fitting and design.', explore: 'Gradient descent, Newton, and convergence.', what: 'Iteratively adjust variables to lower (or raise) an objective. Gradient descent follows the slope; Newton uses curvature.', name: 'Optimisation — finding the best (extremum).', physical: 'Used in fitting models to data, designing systems, training neural networks.', quick: 'Find the bottom of a valley (or top of a hill) by following the slope. Gradient descent is simple; Newton is faster but needs curvature.', physics: '∇f points uphill; move opposite to descend.', math: 'Newton: x_{n+1} = x_n − H⁻¹∇f.', equations: [{ eq: 'x_{n+1} = x_n − η ∇f', label: 'Gradient descent' }], calculated: ['Optimal parameters', 'Convergence'], used: 'Machine learning, engineering design, data fitting, control.', observe: 'Small learning rate = slow; too large = divergence; Newton converges fast near the optimum.', why: 'Following the gradient reduces the objective each step.', assumptions: ['Smooth f', 'Good initial guess'], limitations: ['Local minima trap descent', 'Newton needs Hessian'], controls: { 'Step size (η)': { desc: 'Too big diverges, too small crawls.', unit: '—' } }, viz: { 'Descent path': 'Down the surface to the minimum.' } },
};

