// FLUID & CONTINUUM PHYSICS
const fluid = {
  flow: { ...fluidBase, means: 'Fluid flow is the motion of a liquid or gas, described by a velocity field.', explore: 'Streamlines, speed, and pressure.', what: 'Each point in the fluid has a velocity; streamlines trace the flow. Speed and pressure vary together (Bernoulli).', name: 'Flow — continuous movement of a fluid.', physical: 'Mass is conserved: what flows in must flow out (continuity).', quick: 'Fluid flow is a field of velocities. Streamlines show where it goes; faster flow means lower pressure (Bernoulli).', physics: 'Continuity: A₁v₁ = A₂v₂. Bernoulli: p + ½ρv² + ρgh = const.', math: 'Incompressible: ∇·v = 0.', equations: [{ eq: 'A₁ v₁ = A₂ v₂', label: 'Continuity' }], calculated: ['Velocity field', 'Flow rate', 'Pressure'], used: 'Plumbing, aerodynamics, rivers, respiration.', observe: 'Narrowing a pipe speeds the flow; widening slows it.', why: 'Conservation of mass forces speed to adjust to area.', assumptions: ['Incompressible', 'Steady'], limitations: ['Compressible flow differs', 'Unsteady flow is complex'], controls: { 'Pipe area (A)': { desc: 'Narrower = faster.', unit: 'm²' } }, viz: { 'Streamlines': 'Tangent to velocity.' } },
  pressure: { ...fluidBase, means: 'Fluid pressure is force per unit area exerted by a fluid — static (depth) or dynamic (motion).', explore: 'Static pressure, hydrostatic, and dynamic pressure.', what: 'Static pressure rises with depth (p = ρgh); dynamic pressure rises with speed (½ρv²). Together they\'re conserved (Bernoulli).', name: 'Pressure — force per area (pascal).', physical: 'Hydrostatic: p = ρgh. Dynamic: q = ½ρv².', quick: 'Pressure is the push of a fluid. Deeper = more (hydrostatic); faster = more (dynamic). Bernoulli trades one for the other.', physics: 'p_total = p_static + ½ρv² + ρgh = const (along a streamline).', math: 'Atmospheric pressure ~101 kPa at sea level.', equations: [{ eq: 'p = ρ g h', label: 'Hydrostatic pressure' }, { eq: 'q = ½ ρ v²', label: 'Dynamic pressure' }], calculated: ['Pressure at depth', 'Pressure in flow'], used: 'Dams, submarines, hydraulics, weather (atmospheric).', observe: 'Pressure increases linearly with depth; faster flow lowers static pressure.', why: 'Weight of fluid above creates hydrostatic pressure; motion creates dynamic pressure.', assumptions: ['Incompressible', 'Static or steady'], limitations: ['Compressible at high speeds', 'Atmosphere is non-uniform'], controls: { 'Depth (h)': { desc: 'Sets hydrostatic pressure.', unit: 'm' }, 'Speed (v)': { desc: 'Sets dynamic pressure.', unit: 'm/s' } }, viz: { 'Pressure gradient': 'Increases with depth.' } },
  buoyancy: { ...fluidBase, means: 'Buoyancy is the upward force on an object immersed in a fluid — equal to the weight of fluid displaced.', explore: 'Archimedes\' principle, density, and floating.', what: 'An object feels an upward force = ρ_fluid × V_displaced × g. It floats if its average density is less than the fluid\'s.', name: 'Buoyancy — from Greek buoy, to float; Archimedes\' principle.', physical: 'Why ships float and balloons rise: displaced fluid\'s weight pushes back up.', quick: 'An object in fluid gets an upward push equal to the weight of fluid it pushes aside. Lighter than fluid → float; heavier → sink.', physics: 'F_b = ρ_f V_disp g. Floats when ρ_object < ρ_fluid.', math: 'Ice floats because it\'s less dense than water (anomalous).', equations: [{ eq: 'F_b = ρ_fluid V_displaced g', label: 'Archimedes' }], calculated: ['Buoyant force', 'Float/sink condition'], used: 'Ships, submarines, balloons, hydrometers, fish swim bladders.', observe: 'More submerged volume → more buoyancy; denser fluid lifts more.', why: 'Pressure is higher at the bottom of the object than the top, giving a net upward force.', assumptions: ['Uniform fluid', 'Gravity'], limitations: ['Surface tension for tiny objects', 'Compressibility for gases'], controls: { 'Object density (ρ_obj)': { desc: 'Less than fluid → float.', unit: 'kg/m³' }, 'Displaced volume': { desc: 'Sets the buoyant force.', unit: 'm³' } }, viz: { 'Force diagram': 'Weight down, buoyancy up.' } },
  bernoulli: { ...fluidBase, means: "Bernoulli's equation states that along a streamline, pressure + kinetic + potential energy per volume is constant.", explore: 'Pressure–speed trade-off, and applications.', what: 'Where flow speeds up, pressure drops; where it slows, pressure rises. Energy is conserved along a streamline.', name: 'Daniel Bernoulli (1738).', physical: 'p + ½ρv² + ρgh = const. Explains lift, curveballs, and aspirators.', quick: 'Faster fluid = lower pressure. This is why planes fly (lift), perfume sprayers work, and shower curtains cling.', physics: 'Derived from energy conservation for inviscid, incompressible, steady flow.', math: 'Lift ∝ ½ρv² × area × coefficient.', equations: [{ eq: 'p + ½ρv² + ρgh = const', label: "Bernoulli's equation" }], calculated: ['Pressure differences', 'Lift', 'Flow speeds'], used: 'Aerodynamics, carburettors, pitot tubes (airspeed), wind instruments.', observe: 'Narrowing a pipe speeds flow and drops pressure; widening raises it.', why: 'Energy is conserved; kinetic and pressure energy trade along a streamline.', assumptions: ['Inviscid', 'Incompressible', 'Steady', 'Along a streamline'], limitations: ['Real fluids have viscosity', 'Compressibility at high speed', 'Energy losses in turbulence'], controls: { 'Speed (v)': { desc: 'Higher = lower pressure.', unit: 'm/s' } }, viz: { 'Pressure vs speed': 'Inverse along a streamline.' } },
  viscosity: { ...fluidBase, means: 'Viscosity is a fluid\'s resistance to flow — internal friction between layers moving at different speeds.', explore: 'Shear stress, velocity gradients, and the no-slip condition.', what: 'Thick fluids (honey) have high viscosity; thin ones (water) low. It arises from molecular friction between layers.', name: 'Viscosity — from Latin viscum, "mistletoe" (sticky).', physical: 'Newtonian: τ = μ du/dy. μ is the dynamic viscosity.', quick: 'Viscosity is a fluid\'s thickness — how hard it is to pour. Honey is viscous; water isn\'t. It damps motion and smooths flow.', physics: 'No-slip condition: fluid at a wall is stationary; layers shear.', math: 'Kinematic viscosity ν = μ/ρ.', equations: [{ eq: 'τ = μ du/dy', label: 'Newtonian viscosity' }], calculated: ['Shear stress', 'Flow resistance', 'Damping'], used: 'Lubrication, blood flow, polymer processing, weather.', observe: 'Higher μ = slower, smoother flow; lower μ = faster, more turbulent.', why: 'Molecular friction between layers resists relative motion.', assumptions: ['Newtonian (linear) fluid'], limitations: ['Non-Newtonian fluids (ketchup, blood) aren\'t linear', 'Temperature changes μ strongly'], controls: { 'Viscosity (μ)': { desc: 'Higher = more friction, slower flow.', unit: 'Pa·s' } }, viz: { 'Velocity profile': 'Parabolic in a pipe (laminar).' } },
  laminar: { ...fluidBase, means: 'Laminar flow is smooth, orderly flow in parallel layers with no mixing between them.', explore: 'Streamlines, low Reynolds number, and parabolic profiles.', what: 'At low Re, flow is smooth: layers slide past each other, no eddies. Pipe flow is parabolic.', name: 'Laminar — layered (Latin lamina, "thin sheet").', physical: 'Re < ~2300 in a pipe → laminar; predictable and reversible.', quick: 'Laminar flow is smooth and layered — like honey pouring. Low speed, high viscosity, or small size keep it orderly.', physics: 'Pipe velocity profile: v(r) = v_max(1 − r²/R²).', math: 'Hagen–Poiseuille: Q = πR⁴Δp/(8μL).', equations: [{ eq: 'Q = π R⁴ Δp / (8 μ L)', label: 'Poiseuille flow' }], calculated: ['Flow rate', 'Velocity profile', 'Pressure drop'], used: 'Microfluidics, blood capillaries, lubrication, precision flow.', observe: 'Flow rate scales as R⁴ — a tiny widening hugely increases flow.', why: 'Viscosity dominates inertia; layers don\'t mix, so flow stays smooth.', assumptions: ['Low Re', 'Newtonian', 'Steady'], limitations: ['Transitions to turbulence above Re ~2300', 'Entrance effects'], controls: { 'Pipe radius (R)': { desc: 'Flow ∝ R⁴ — very sensitive.', unit: 'm' } }, viz: { 'Parabolic profile': 'Fastest at centre, zero at walls.' } },
  turbulent: { ...fluidBase, means: 'Turbulent flow is chaotic, mixing flow with eddies and vortices across many scales.', explore: 'High Reynolds number, mixing, and energy cascade.', what: 'At high Re, inertia overwhelms viscosity; flow breaks into chaotic eddies that mix efficiently.', name: 'Turbulent — from Latin turbo, "whirl".', physical: 'Energy cascades from large eddies to small ones, dissipating as heat (Kolmogorov).', quick: 'Turbulent flow is chaotic and mixing — like a rushing river. High speed or low viscosity triggers it; it\'s everywhere in nature but unsolved analytically.', physics: 'Re > ~4000 in a pipe. No general closed-form solution.', math: 'Kolmogorov spectrum: E(k) ∝ k^(−5/3).', equations: [{ eq: 'Re > ~4000 (pipe)', label: 'Turbulent regime' }], calculated: ['Mixing', 'Drag', 'Energy dissipation'], used: 'Aerodynamics, weather, combustion, mixing processes.', observe: 'Turbulence mixes fluids rapidly and increases drag.', why: 'Inertia destabilises smooth flow; eddies form and cascade energy to small scales where viscosity dissipates it.', assumptions: ['High Re', 'Newtonian'], limitations: ['No full analytic theory', 'Must be simulated (DNS/LES/RANS)'], controls: { 'Re': { desc: 'Higher = more turbulent.', unit: '—' } }, viz: { 'Eddies': 'Chaotic swirling at many scales.' } },
  reynolds: { ...fluidBase, means: 'The Reynolds number Re = ρvL/μ predicts whether flow is laminar or turbulent.', explore: 'The ratio of inertia to viscosity, and regime thresholds.', what: 'Re is the ratio of inertial to viscous forces. Low Re → laminar; high Re → turbulent. It\'s the key dimensionless number of fluid dynamics.', name: 'Osborne Reynolds (1883).', physical: 'Re < ~2300 laminar, ~2300–4000 transitional, > 4000 turbulent (pipe).', quick: 'Re tells you if flow is smooth or chaotic. Low Re = viscous, laminar; high Re = inertial, turbulent. Same Re = same flow regime (similarity).', physics: 'Re = ρvL/μ = vL/ν (kinematic viscosity ν).', math: 'Dynamic similarity: models match real flow when Re matches.', equations: [{ eq: 'Re = ρ v L / μ', label: 'Reynolds number' }], calculated: ['Flow regime', 'Similarity scaling'], used: 'Wind tunnels, ship/aircraft design, blood flow, weather.', observe: 'A small fast model can match a large slow one if Re is the same.', why: 'Re compares the two forces shaping the flow; whichever dominates sets the regime.', assumptions: ['Newtonian fluid', 'Characteristic length L defined'], limitations: ['Thresholds depend on geometry', 'Transitions are not perfectly sharp'], controls: { 'Speed (v)': { desc: 'Raises Re.', unit: 'm/s' }, 'Size (L)': { desc: 'Raises Re.', unit: 'm' }, 'Viscosity (μ)': { desc: 'Lowers Re.', unit: 'Pa·s' } }, viz: { 'Regime map': 'Laminar → transitional → turbulent.' } },
  pipe: { ...fluidBase, means: 'Pipe flow studies how fluids move through conduits — pressure drop, flow rate, and profile.', explore: 'Poiseuille flow, pressure drop, and the R⁴ law.', what: 'In a laminar pipe, flow is parabolic and the flow rate scales as the fourth power of radius (Poiseuille).', name: 'Poiseuille — Jean Poiseuille (1840s), studied blood/pipe flow.', physical: 'Q = πR⁴Δp/(8μL) — a tiny radius change hugely affects flow.', quick: 'Flow through a pipe: the wider it is, the vastly more it carries (R⁴ law). Pressure drops along the pipe due to viscosity.', physics: 'Laminar: parabolic profile. Turbulent: flatter profile, more drag.', math: 'Pressure drop Δp = 8μLQ/(πR⁴).', equations: [{ eq: 'Q = π R⁴ Δp / (8 μ L)', label: 'Poiseuille (laminar)' }], calculated: ['Flow rate', 'Pressure drop', 'Velocity profile'], used: 'Plumbing, blood flow, microfluidics, oil pipelines.', observe: 'Doubling radius increases laminar flow 16×; turbulence raises drag.', why: 'Viscous resistance in the pipe sets the pressure–flow relation; radius dominates.', assumptions: ['Laminar', 'Newtonian', 'Rigid pipe'], limitations: ['Turbulence changes the law', 'Flexible pipes (blood vessels) differ'], controls: { 'Radius (R)': { desc: 'Flow ∝ R⁴.', unit: 'm' }, 'Length (L)': { desc: 'Longer = more resistance.', unit: 'm' } }, viz: { 'Parabolic profile': 'In laminar pipe flow.' } },
  drag: { ...fluidBase, means: 'Drag is the force opposing an object\'s motion through a fluid.', explore: 'Linear and quadratic drag, and the drag coefficient.', what: 'At low speed, drag ∝ v (viscous); at high speed, drag ∝ v² (inertial/pressure). The drag coefficient C_d captures shape.', name: 'Drag — the resistance a body feels moving through fluid.', physical: 'F_d = ½ρv² C_d A. Streamlining lowers C_d.', quick: 'Drag slows things moving through fluid. Slow objects feel drag ∝ speed; fast ones ∝ speed². Streamlining reduces it.', physics: 'Stokes drag (low Re): F = 6πηrv. High Re: F = ½ρv²C_dA.', math: 'Terminal velocity when drag = gravity.', equations: [{ eq: 'F_d = ½ ρ v² C_d A', label: 'Drag force' }], calculated: ['Drag force', 'Terminal velocity', 'Power needed'], used: 'Aerodynamics, vehicles, falling objects, sports.', observe: 'Streamlined shapes have lower C_d; terminal velocity balances drag and weight.', why: 'Fluid must be pushed aside and around the body; faster motion means more momentum transfer per second.', assumptions: ['Given C_d', 'Newtonian fluid'], limitations: ['C_d varies with Re', 'Compressibility at high speed'], controls: { 'Speed (v)': { desc: 'Drag ∝ v² (high Re).', unit: 'm/s' }, 'Area (A)': { desc: 'Frontal area; bigger = more drag.', unit: 'm²' } }, viz: { 'Drag vs speed': 'Quadratic rise.' } },
  atmos: { ...fluidBase, means: 'Atmospheric pressure is the pressure exerted by the column of air above a point — it decreases with altitude.', explore: 'Barometric formula, scale height, and layers.', what: 'At sea level ~101 kPa; it drops exponentially with height because less air sits above. Scale height ~8 km.', name: 'Atmospheric — of the atmosphere.', physical: 'p(h) = p₀ e^(−h/H), H = kT/(mg) ~ 8 km.', quick: 'Air pressure is the weight of the air above you. It falls exponentially with altitude — half gone by ~5.5 km. Why high-altitude breathing is hard.', physics: 'Hydrostatic equilibrium of the atmosphere.', math: 'Temperature varies by layer (troposphere, stratosphere, etc.).', equations: [{ eq: 'p(h) = p₀ e^(−h/H)', label: 'Barometric formula', where: 'H = scale height' }], calculated: ['Pressure at altitude', 'Air density'], used: 'Aviation, meteorology, alpine physiology, weather.', observe: 'Pressure halves roughly every 5.5 km; density too.', why: 'Higher up, less air weighs down on you, so pressure drops.', assumptions: ['Isothermal atmosphere (approx)', 'Ideal gas'], limitations: ['Real atmosphere has temperature layers', 'Humidity matters'], controls: { 'Altitude (h)': { desc: 'Higher = lower pressure.', unit: 'm' } }, viz: { 'Pressure vs altitude': 'Exponential decay.' } },
  waveprop: { ...fluidBase, means: 'Wave propagation in fluids is the travel of pressure/density disturbances — sound is the prime example.', explore: 'Speed of sound, compression waves, and shock fronts.', what: 'A disturbance in a fluid travels as a pressure wave at the speed of sound; large disturbances can steepen into shocks.', name: 'Wave propagation — disturbance travel through a medium.', physical: 'c = √(B/ρ) (bulk modulus over density).', quick: 'Push a fluid and the push travels as a pressure wave — sound. Strong pushes can steepen into shock waves (supersonic).', physics: 'Linear: sound. Non-linear: shocks form when wave speed depends on amplitude.', math: 'Mach number M = v/c; M > 1 = supersonic.', equations: [{ eq: 'c = √(B / ρ)', label: 'Speed of sound' }], calculated: ['Wave speed', 'Shock formation'], used: 'Acoustics, aerodynamics, seismology, explosions.', observe: 'Sound is faster in stiffer/denser media; shocks form at supersonic speeds.', why: 'Stiffer media restore shape faster, transmitting disturbances quicker.', assumptions: ['Linear acoustics (small amplitude)'], limitations: ['Shocks are non-linear', 'Real media disperse/absorb'], controls: { 'Bulk modulus (B)': { desc: 'Stiffer = faster sound.', unit: 'Pa' } }, viz: { 'Pressure wave': 'Travelling compression.' } },
  shock: { ...fluidBase, means: 'A shock wave is a sharp, non-linear pressure front formed when an object moves faster than the sound speed.', explore: 'Supersonic fronts, Mach cone, and jump conditions.', what: 'When flow exceeds the sound speed, disturbances pile up into a near-discontinuous front — a shock. Across it, pressure, density, and temperature jump.', name: 'Shock — a sudden, abrupt wave front.', physical: 'Mach cone angle: sinμ = 1/M. Across a shock, Rankine–Hugoniot relations hold.', quick: 'Move faster than sound and disturbances merge into a sharp wall — a shock. It\'s the sonic boom, the crack of a whip, and the nose of a supersonic jet.', physics: 'Across a normal shock: mass, momentum, energy conserved; entropy rises (irreversible).', math: 'M > 1 upstream; M < 1 downstream (subsonic behind shock).', equations: [{ eq: 'sin μ = 1/M', label: 'Mach cone angle' }], calculated: ['Shock angle', 'Post-shock conditions'], used: 'Supersonic flight, explosions, astrophysics (supernovae), shock tubes.', observe: 'Shocks compress and heat the flow; they\'re irreversible (entropy rises).', why: 'Supersonic motion lets wavefronts overlap, forming a sharp front rather than a smooth wave.', assumptions: ['Ideal gas', 'Steady shock'], limitations: ['Real shocks have finite thickness', 'Curved shocks differ'], controls: { 'Mach number (M)': { desc: 'M > 1 = supersonic.', unit: '—' } }, viz: { 'Mach cone': 'V-shape trailing the object.' } },
  navier: { ...fluidBase, means: 'The Navier–Stokes equations are the fundamental equations of fluid motion — conservation of momentum for a continuum.', explore: 'The full equations, incompressibility, and turbulence.', what: 'They describe how a fluid\'s velocity field evolves under pressure, viscosity, and body forces. Solving them (especially for turbulence) is a million-dollar open problem.', name: 'Claude-Louis Navier & George Stokes (19th c.).', physical: 'This simulator solves a 2D stable-fluids scheme (Jos Stam).', quick: 'Navier–Stokes are the "F=ma" of fluids. They predict flow everywhere — but turbulence makes them famously hard, and a full proof of regularity is an unsolved millennium problem.', physics: 'ρ(∂v/∂t + v·∇v) = −∇p + μ∇²v + f, with ∇·v = 0 (incompressible).', math: 'Solved numerically: split into advection, diffusion, pressure projection.', equations: [{ eq: 'ρ(∂v/∂t + v·∇v) = −∇p + μ∇²v + f', label: 'Navier–Stokes' }], calculated: ['Velocity field', 'Pressure', 'Vorticity'], used: 'All of fluid dynamics — weather, aerodynamics, blood, oceans.', observe: 'Viscosity diffuses momentum; pressure enforces incompressibility; advection moves vorticity.', why: 'Conservation of momentum + viscosity + pressure gives the full fluid behaviour.', assumptions: ['Continuum', 'Newtonian'], limitations: ['Turbulence unresolved analytically', 'Compressibility adds terms', 'Molecular scales break it'], controls: { 'Viscosity (ν)': { desc: 'Diffuses momentum; higher = smoother.', unit: 'm²/s' }, 'Forcing': { desc: 'Drives the flow (e.g., a vortex source).', unit: '—' } }, viz: { 'Velocity field': 'Arrows + vorticity colours.' } },
};

