// CONDENSED MATTER & MATERIALS
const condensed = {
  crystal: { ...condensedBase, means: 'A crystal structure is a periodic, repeating arrangement of atoms in a solid.', explore: 'Lattice, basis, and symmetry.', what: 'Atoms sit on a repeating 3D grid (lattice) with a motif (basis) at each point. The periodicity gives crystals their sharp diffraction patterns and bands.', name: 'Crystal — from Greek krystallos, "ice/clear ice".', physical: 'Periodicity → Bloch\'s theorem → band structure.', quick: 'A crystal is atoms in a repeating 3D pattern. That regularity is why crystals have distinct bands, sharp X-ray diffraction, and clean material properties.', physics: 'Lattice + basis = crystal structure.', math: 'Translation symmetry underpins Bloch states.', equations: [{ eq: 'ψ_k(r) = e^(ik·r) u_k(r)', label: 'Bloch theorem' }], calculated: ['Lattice geometry', 'Symmetry', 'Diffraction peaks'], used: 'Semiconductors, X-ray crystallography, materials science.', observe: 'Different lattice types (FCC, BCC, etc.) give different packing and properties.', why: 'Periodicity lets electrons propagate as waves (Bloch states), enabling bands.', assumptions: ['Perfect periodicity'], limitations: ['Real crystals have defects', 'Surfaces break periodicity'], controls: { 'Lattice type': { desc: 'Sets the repeating geometry.', unit: '—' } }, viz: { 'Unit cell': 'The repeating block.' } },
  unitcell: { ...condensedBase, means: 'A unit cell is the smallest repeating block of a crystal lattice.', explore: 'Primitive cells, lattice points, and packing.', what: 'Tiling the unit cell fills all space without gaps. Its shape and contents define the crystal.', name: 'Unit cell — the repeating tile.', physical: 'Primitive cell has one lattice point; conventional cells may have more for symmetry.', quick: 'The unit cell is the smallest tile that, repeated, builds the whole crystal. Its shape decides the crystal\'s symmetry and properties.', physics: 'Lattice vectors a, b, c define the cell.', math: 'Packing fraction depends on lattice (FCC ~74%, BCC ~68%).', equations: [{ eq: 'V_cell = a · (b × c)', label: 'Cell volume' }], calculated: ['Cell volume', 'Packing fraction', 'Atomic density'], used: 'Crystallography, materials design.', observe: 'FCC and HCP pack most efficiently (~74%).', why: 'The cell captures the repeating unit; its geometry sets density and symmetry.', assumptions: ['Periodic lattice'], limitations: ['Real cells distort', 'Defects break repetition'], controls: { 'Lattice vectors': { desc: 'Set cell shape.', unit: 'Å' } }, viz: { 'Tiled cells': 'Fill space.' } },
  bravais: { ...condensedBase, means: 'Bravais lattices are the 14 distinct 3D lattice types that crystals can have.', explore: 'Symmetry classes and the 14 types.', what: 'Every periodic 3D lattice is one of 14 Bravais types (cubic, tetragonal, orthorhombic, …), classified by symmetry.', name: 'Auguste Bravais (1850).', physical: 'Symmetry determines physical properties (e.g., isotropy, piezoelectricity).', quick: 'Only 14 distinct 3D lattice patterns exist — the Bravais lattices. Each has a symmetry that shapes the material\'s behaviour.', physics: 'Classified by translation + point symmetry.', math: 'Cubic (3), tetragonal (2), orthorhombic (4), monoclinic (2), triclinic (1), hexagonal (1), trigonal (1).', equations: [{ eq: '14 Bravais lattices in 3D', label: 'Classification' }], calculated: ['Symmetry class', 'Allowed properties'], used: 'Crystallography, predicting material anisotropy.', observe: 'Higher symmetry (cubic) → more isotropic properties.', why: 'Symmetry constrains physical tensors (e.g., no piezoelectricity in centrosymmetric crystals).', assumptions: ['Perfect lattice'], limitations: ['Real crystals have defects and disorder'], controls: { 'Lattice type': { desc: 'One of 14.', unit: '—' } }, viz: { 'Symmetry classes': 'The 14 types.' } },
  reciprocal: { ...condensedBase, means: 'The reciprocal lattice is the Fourier transform of the real lattice — it lives in k-space and governs diffraction and bands.', explore: 'k-space, Brillouin zones, and diffraction peaks.', what: 'Each real-space lattice has a reciprocal lattice in momentum space. Diffraction peaks and band structure live there.', name: 'Reciprocal — inverse space (momentum/frequency).', physical: 'Bragg diffraction occurs at reciprocal-lattice points; bands are plotted along reciprocal directions.', quick: 'The reciprocal lattice is the crystal\'s "shadow" in momentum space. X-ray diffraction peaks and electron bands are labelled by it.', physics: 'b₁ = 2π (a₂×a₃)/V; reciprocal vectors are perpendicular to real planes.', math: 'Brillouin zone = the Wigner-Seitz cell of the reciprocal lattice.', equations: [{ eq: 'b₁ = 2π (a₂ × a₃) / V', label: 'Reciprocal lattice vector' }], calculated: ['Diffraction peaks', 'Band path', 'Brillouin zone'], used: 'X-ray diffraction, band-structure calculations, phonon spectra.', observe: 'Diffraction peaks sit at reciprocal-lattice points; bands are traced between high-symmetry points.', why: 'Fourier duality: periodicity in real space gives discrete points in k-space.', assumptions: ['Periodic lattice'], limitations: ['Defects broaden peaks'], controls: { 'Real lattice': { desc: 'Determines the reciprocal lattice.', unit: 'Å' } }, viz: { 'Reciprocal lattice': 'Points in k-space.' } },
  band: { ...condensedBase, means: 'Band structure is the allowed energy vs momentum relation for electrons in a solid — it decides metal vs insulator.', explore: 'E(k) dispersion, gaps, and the Fermi level.', what: 'In a periodic potential, electron energies form bands separated by gaps. If the Fermi level sits in a gap → insulator/semiconductor; in a band → metal.', name: 'Band — a continuous range of allowed energies.', physical: 'Tight-binding: E(k) = ε₀ ± t(1 − cos ka) (1D). The gap at the zone edge opens a band gap.', quick: 'Bands are the allowed electron energies in a solid. A gap at the Fermi level makes an insulator/semiconductor; no gap makes a metal. This is why silicon is special.', physics: 'Band gap Eg separates valence and conduction bands.', math: 'Fermi level position decides conduction.', equations: [{ eq: 'E(k) = ε₀ ± t(1 − cos ka)', label: 'Tight-binding bands' }], calculated: ['Band edges', 'Gap size', 'Effective mass'], used: 'Semiconductors, LEDs, solar cells, transistors, all electronics.', observe: 'Larger gap → more insulating; no gap → conducting; small gap → semiconductor.', why: 'Periodicity creates bands; the gap size and Fermi position decide conduction.', assumptions: ['Periodic potential', 'Independent electrons'], limitations: ['Strong correlations break it', 'Disorder creates localised states'], controls: { 'Hopping (t)': { desc: 'Sets bandwidth.', unit: 'eV' }, 'Gap (Eg)': { desc: 'Metal vs semiconductor.', unit: 'eV' } }, viz: { 'E(k) plot': 'Bands with a gap.' } },
  dos: { ...condensedBase, means: 'The density of states (DOS) is the number of electron states per unit energy — where electrons can live.', explore: 'g(E), van Hove singularities, and filling.', what: 'DOS g(E) counts how many states exist at each energy. Peaks (van Hove singularities) occur at band edges in low dimensions.', name: 'Density of states — states per energy.', physical: 'High DOS at the Fermi level → many conduction electrons; a gap → none.', quick: 'The DOS shows how many electron states exist at each energy. Peaks mean many states; a gap means none. It predicts conductivity and optical absorption.', physics: 'g(E) = (1/2π²)(2m/ℏ²)^(3/2) √E (3D free electron).', math: 'Van Hove singularities: 1D ∝ 1/√E, 2D step-like.', equations: [{ eq: 'g(E) ∝ √E  (3D free electron)', label: 'Free-electron DOS' }], calculated: ['State count', 'Carrier density', 'Optical absorption'], used: 'Semiconductors, superconductors, spectroscopy.', observe: 'A gap in the DOS → insulator; finite DOS at E_F → metal.', why: 'Band structure sets where states cluster; dimensionality sets the singularity type.', assumptions: ['Known bands'], limitations: ['Disorder broadens', 'Interactions shift peaks'], controls: { 'Dimension': { desc: 'Changes singularity type.', unit: '—' } }, viz: { 'g(E) plot': 'Peaks and gaps.' } },
  semicon: { ...condensedBase, means: 'A semiconductor has a small band gap — it conducts when given energy (heat, light, doping).', explore: 'Gap, doping, and carrier control.', what: 'A small gap (~1 eV) lets electrons jump from valence to conduction band, creating carriers. Doping adds extra carriers (n- or p-type).', name: 'Semi-conductor — between conductor and insulator.', physical: 'Silicon Eg ~1.1 eV; GaAs ~1.4 eV. Doping adds donors (n) or acceptors (p).', quick: 'Semiconductors have a small gap: they conduct only when energised. Doping lets us control carriers — the basis of all transistors and chips.', physics: 'n-type: extra electrons; p-type: extra holes. A PN junction is the building block.', math: 'Conductivity σ = n e μ (carriers × mobility).', equations: [{ eq: 'σ = n e μ', label: 'Conductivity', where: 'n = carrier density, μ = mobility' }], calculated: ['Carrier density', 'Conductivity', 'Junction behaviour'], used: 'Transistors, diodes, solar cells, LEDs, all modern electronics.', observe: 'Higher T or doping raises carriers and conductivity.', why: 'A small gap allows thermal/optical excitation; doping adds carriers directly.', assumptions: ['Small gap', 'Dopable'], limitations: ['Real semiconductors have defects', 'Temperature affects mobility'], controls: { 'Gap (Eg)': { desc: 'Sets intrinsic carrier density.', unit: 'eV' }, 'Doping': { desc: 'Adds carriers (n or p).', unit: 'cm⁻³' } }, viz: { 'Band diagram': 'Gap with Fermi level.' } },
  pn: { ...condensedBase, means: 'A PN junction is the interface between p-type and n-type semiconductor — the building block of diodes and transistors.', explore: 'Depletion region, built-in field, and biasing.', what: 'At the junction, electrons and holes recombine, leaving a depletion region with a built-in electric field that blocks further current — until you apply bias.', name: 'PN — p-type (holes) meets n-type (electrons).', physical: 'Forward bias shrinks the barrier (current flows); reverse bias widens it (blocks).', quick: 'A PN junction is where p and n semiconductors meet. It conducts one way (forward) and blocks the other (reverse) — the diode, and the heart of every transistor.', physics: 'Built-in potential V_bi ~ Eg/e. Depletion width ∝ √(V_bi − V).', math: 'I-V is exponential in forward bias (Shockley equation).', equations: [{ eq: 'I = I_s (e^(eV/kT) − 1)', label: 'Shockley diode equation' }], calculated: ['Depletion width', 'Built-in field', 'I-V curve'], used: 'Diodes, transistors, solar cells, LEDs, all electronics.', observe: 'Forward bias → current; reverse bias → tiny leakage until breakdown.', why: 'The built-in field separates carriers; bias tilts the balance to allow or block current.', assumptions: ['Abrupt junction', 'Low injection'], limitations: ['Real junctions have recombination', 'Breakdown at high reverse bias'], controls: { 'Doping levels': { desc: 'Set V_bi and depletion width.', unit: 'cm⁻³' }, 'Bias (V)': { desc: 'Forward = conduct; reverse = block.', unit: 'V' } }, viz: { 'Band bending': 'At the junction.' } },
  diode: { ...condensedBase, means: 'A diode is a PN junction that conducts in one direction — the simplest semiconductor device.', explore: 'I-V curve, forward/reverse bias, and breakdown.', what: 'Forward bias: exponential current. Reverse bias: tiny leakage until breakdown. The one-way valve of electronics.', name: 'Diode — two-terminal (di-ode) device.', physical: 'I = I_s(e^(eV/kT) − 1).', quick: 'A diode lets current flow one way only. Forward = on; reverse = off (until breakdown). It\'s the simplest semiconductor device and the basis of rectifiers.', physics: 'Built-in field blocks reverse; forward bias overcomes it.', math: 'Turn-on voltage ~0.7 V (Si).', equations: [{ eq: 'I = I_s (e^(eV/kT) − 1)', label: 'Diode I-V' }], calculated: ['Current vs voltage', 'Turn-on voltage', 'Breakdown'], used: 'Rectifiers, protection, LEDs, photodetectors, logic.', observe: 'Exponential rise in forward; flat leakage in reverse; sharp breakdown.', why: 'The junction\'s built-in field sets the one-way behaviour.', assumptions: ['Ideal PN junction'], limitations: ['Real diodes have resistance and capacitance', 'Breakdown modes differ'], controls: { 'Bias (V)': { desc: 'Forward = conduct; reverse = block.', unit: 'V' } }, viz: { 'I-V curve': 'Exponential forward, flat reverse.' } },
  hall: { ...condensedBase, means: 'The Hall effect is a voltage perpendicular to current and magnetic field in a conductor — it reveals carrier type and density.', explore: 'Hall voltage, carrier sign, and density.', what: 'Current + B field deflects carriers sideways, creating a transverse voltage. Its sign reveals whether carriers are + or − (electrons vs holes).', name: 'Edwin Hall (1879).', physical: 'V_H = I B / (n e t). Sign of V_H distinguishes electron vs hole conduction.', quick: 'A magnetic field bends moving charges sideways, making a transverse voltage. The voltage\'s sign tells you if carriers are electrons or holes — and how many.', physics: 'Hall coefficient R_H = 1/(n e).', math: 'Used to measure carrier density and type in semiconductors.', equations: [{ eq: 'V_H = I B / (n e t)', label: 'Hall voltage' }, { eq: 'R_H = 1/(n e)', label: 'Hall coefficient' }], calculated: ['Carrier density', 'Carrier type (sign)', 'Mobility'], used: 'Semiconductor characterisation, magnetic sensors, quantum Hall effect.', observe: 'Reversing B or carrier type flips the Hall voltage sign.', why: 'The Lorentz force pushes carriers sideways; the balance with the Hall field gives the voltage.', assumptions: ['Single carrier type', 'Thin sample'], limitations: ['Multi-carrier systems are complex', 'Quantum Hall at low T, high B'], controls: { 'B field': { desc: 'Sets deflection.', unit: 'T' }, 'Current (I)': { desc: 'Sets Hall voltage.', unit: 'A' } }, viz: { 'Hall voltage': 'Transverse to current and B.' } },
  ferro: { ...condensedBase, means: 'Ferromagnetism is spontaneous magnetic order — a material stays magnetised even without an external field.', explore: 'Spontaneous magnetisation, Curie temperature, and hysteresis.', what: 'Below the Curie temperature T_c, spins align spontaneously, giving a permanent magnet. Above T_c, thermal disorder destroys it.', name: 'Ferro — iron (the first known ferromagnet).', physical: 'Exchange interaction aligns spins; order parameter M(T) rises below T_c.', quick: 'A ferromagnet is a permanent magnet: spins align on their own below the Curie temperature. Heat it past T_c and magnetism vanishes.', physics: 'M(T) ∝ (T_c − T)^β near T_c (critical exponent).', math: 'Hysteresis: M lags behind H (memory).', equations: [{ eq: 'M ∝ (T_c − T)^β', label: 'Order parameter below T_c' }], calculated: ['Magnetisation', 'Curie temperature', 'Hysteresis loop'], used: 'Permanent magnets, data storage, transformers, motors.', observe: 'M appears below T_c; cycling H gives a hysteresis loop with remanence.', why: 'Exchange interaction favours alignment; thermal noise fights it; below T_c, order wins.', assumptions: ['Exchange-coupled spins', 'Uniform material'], limitations: ['Real magnets have domains', 'Anisotropy matters'], controls: { 'Temperature (T)': { desc: 'Drives order; above T_c → no magnet.', unit: 'K' }, 'Field (H)': { desc: 'Aligns domains; causes hysteresis.', unit: 'A/m' } }, viz: { 'M(T) curve': 'Rises below T_c.', 'Hysteresis loop': 'M vs H.' } },
  antiferro: { ...condensedBase, means: 'Antiferromagnetism is alternating spin order — neighbouring spins point oppositely, giving no net magnetisation.', explore: 'Staggered order, Néel temperature, and spin structure.', what: 'Spins alternate up/down on neighbouring sites. Net magnetisation is zero, but there\'s hidden order (detectable by neutron scattering).', name: 'Anti-ferro — alternating, not aligned.', physical: 'Order vanishes above the Néel temperature T_N.', quick: 'In an antiferromagnet, neighbouring spins cancel — no net magnetisation, but hidden alternating order exists until the Néel temperature.', physics: 'Staggered magnetisation is the order parameter.', math: 'Two sublattices with opposite spins.', equations: [{ eq: 'M_staggered ∝ (T_N − T)^β', label: 'Staggered order' }], calculated: ['Néel temperature', 'Spin structure'], used: 'Spintronics, magnetic recording, research (resonant X-ray).', observe: 'No net M, but neutron diffraction reveals the alternating pattern.', why: 'Exchange favours anti-alignment; thermal disorder destroys it above T_N.', assumptions: ['Two sublattices', 'Exchange coupling'], limitations: ['Real materials have frustration', 'Field-induced phases'], controls: { 'Temperature (T)': { desc: 'Above T_N → disorder.', unit: 'K' } }, viz: { 'Spin pattern': 'Alternating up/down.' } },
  ising2: { ...condensedBase, means: 'The Ising model is a lattice of up/down spins that order below a critical temperature — the simplest model of a phase transition.', explore: 'Order, the Curie point, and critical behaviour.', what: 'Spins prefer to align with neighbours. Below T_c they order spontaneously; above, they randomise. The 2D model has an exact solution (Onsager).', name: 'Ernst Ising (1925); Lars Onsager solved 2D (1944).', physical: 'M(T), E(T), C(T), χ(T) all show critical behaviour near T_c.', quick: 'A grid of spins that like to agree. Cold → all align (magnet); hot → random (no magnet). A sharp transition at T_c — the textbook phase transition.', physics: 'T_c = 2J/(k ln(1+√2)) (2D exact).', math: 'Critical exponents are universal.', equations: [{ eq: 'E = −J Σ s_i s_j', label: 'Ising Hamiltonian' }], calculated: ['Magnetisation', 'Energy', 'Heat capacity', 'Susceptibility'], used: 'Magnetism, alloys, neural networks, lattice gases, teaching.', observe: 'Below T_c, M ≠ 0; C and χ peak at T_c.', why: 'Thermal noise fights ordering; below T_c, interactions win and order emerges.', assumptions: ['Nearest-neighbour', '2D square lattice'], limitations: ['Quantum spins differ', 'Finite-size smears T_c'], controls: { 'Temperature (T)': { desc: 'Drives the transition.', unit: 'J/k' }, 'Coupling (J)': { desc: 'Interaction strength.', unit: 'J' } }, viz: { 'Spin lattice': 'Clusters below T_c.' } },
  heisenberg: { ...condensedBase, means: 'The Heisenberg model uses vector spins (not just up/down) — a more realistic model of magnetism.', explore: 'Continuous spin direction, order, and excitations.', what: 'Spins are 3D vectors that can point anywhere. Neighbouring spins prefer to align (ferro) or anti-align (antiferro).', name: 'Werner Heisenberg (1928).', physical: 'Continuous symmetry → Goldstone modes (spin waves, magnons).', quick: 'A more realistic magnet model: spins are arrows, not just up/down. Continuous directions allow spin waves — ripples of magnetisation.', physics: 'Ĥ = −J Σ S_i · S_j.', math: 'Magnons are the low-energy excitations.', equations: [{ eq: 'Ĥ = −J Σ S_i · S_j', label: 'Heisenberg Hamiltonian' }], calculated: ['Order', 'Spin-wave spectrum', 'Critical behaviour'], used: 'Magnetism, neutron scattering, quantum magnetism.', observe: 'Below T_c, spins order; continuous symmetry allows spin waves.', why: 'Vector spins have continuous symmetry, giving soft (Goldstone) modes.', assumptions: ['Classical or quantum spins', 'Exchange coupling'], limitations: ['Anisotropy breaks symmetry', 'Quantum case is harder'], controls: { 'Temperature (T)': { desc: 'Drives order.', unit: 'K' } }, viz: { 'Spin directions': 'Arrows on a lattice.' } },
  xy: { ...condensedBase, means: 'The XY model has planar spins (rotors) — it exhibits the Kosterlitz–Thouless transition.', explore: 'Vortices, the KT transition, and quasi-long-range order.', what: 'Spins are angles in a plane. Below T_KT, vortices bind in pairs; above, they proliferate and destroy order — a topological transition without a conventional order parameter.', name: 'XY — spins in the x-y plane; Kosterlitz & Thouless (Nobel 2016).', physical: 'No true long-range order in 2D (Mermin–Wagner), but quasi-long-range below T_KT.', quick: 'Planar spins on a lattice: below a special temperature, vortex pairs bind and the system has quasi-order; above, vortices unbind and order dies — a topological phase transition.', physics: 'T_KT marks vortex unbinding.', math: 'Correlation decays algebraically below T_KT, exponentially above.', equations: [{ eq: '⟨S_i·S_j⟩ ∝ r^(−η)', label: 'Algebraic order below T_KT' }], calculated: ['Vortex density', 'Correlation exponent', 'T_KT'], used: 'Thin films, superfluids, superconductors, topological physics.', observe: 'Vortex-antivortex pairs below T_KT; free vortices above.', why: 'Vortex binding preserves quasi-order; unbinding destroys it.', assumptions: ['2D', 'Planar spins'], limitations: ['3D differs', 'Finite size affects T_KT'], controls: { 'Temperature (T)': { desc: 'Drives vortex unbinding.', unit: 'K' } }, viz: { 'Vortex pattern': 'Pairs below T_KT.' } },
  supercon: { ...condensedBase, means: 'Superconductivity is zero electrical resistance below a critical temperature — electrons pair up and flow without loss.', explore: 'Critical temperature, the gap, and zero resistance.', what: 'Below T_c, electrons form Cooper pairs (mediated by lattice vibrations) that condense into a frictionless state. Resistance drops to exactly zero.', name: 'Super-conductor — perfect conductor (discovered 1911, Kamerlingh Onnes).', physical: 'BCS theory: pairing opens a gap Δ at the Fermi level.', quick: 'A superconductor conducts with zero resistance below T_c. Electrons pair up and flow without friction — enabling MRI magnets and quantum circuits.', physics: 'Gap Δ ~ 1.7 kT_c (BCS). Meissner effect expels magnetic fields.', math: 'Type I: full Meissner; Type II: vortices allow partial flux.', equations: [{ eq: 'Δ ≈ 1.76 k T_c', label: 'BCS gap' }], calculated: ['T_c', 'Gap', 'Critical field'], used: 'MRI, quantum computers, lossless power transmission, particle accelerators.', observe: 'R = 0 below T_c; fields are expelled (Meissner).', why: 'Cooper pairing + condensation give a gap and frictionless flow.', assumptions: ['BCS (phonon-mediated)', 'Low T'], limitations: ['High-Tc cuprates need beyond-BCS theory', 'Real superconductors have vortices and pinning'], controls: { 'Temperature (T)': { desc: 'Below T_c = superconducting.', unit: 'K' } }, viz: { 'Gap in DOS': 'Opens below T_c.' } },
  phases: { ...condensedBase, means: 'Phase transitions are abrupt changes in a material\'s state (e.g., magnetised↔random, superconducting↔normal) at a critical temperature.', explore: 'Order parameters, critical points, and universality.', what: 'At a critical temperature, a small change flips the system between phases. Order parameters (M, gap) vanish or appear.', name: 'Phase transition — a qualitative change of state.', physical: 'Continuous (2nd order): order turns on smoothly; discontinuous (1st order): jump with latent heat.', quick: 'Heat a magnet past T_c and magnetism vanishes; cool a metal below T_c and it superconducts. Phase transitions are sudden changes of state at critical points.', physics: 'Near criticality, fluctuations grow; universality makes exponents the same across systems.', math: 'M ∝ (T_c − T)^β, C ∝ |T − T_c|^(−α).', equations: [{ eq: 'M ∝ (T_c − T)^β', label: 'Order parameter (critical exponent)' }], calculated: ['Order parameter', 'Critical exponents', 'Phase boundary'], used: 'Magnetism, superconductivity, alloys, liquid crystals, cosmology.', observe: 'C and χ diverge at T_c; universality groups share exponents.', why: 'Interactions + thermal noise balance at a critical point, producing scale-invariant fluctuations.', assumptions: ['Thermodynamic limit'], limitations: ['Finite size rounds the transition', 'Disorder changes universality'], controls: { 'Temperature (T)': { desc: 'Drives the transition.', unit: 'K' } }, viz: { 'Order parameter vs T': 'Rises/falls at T_c.' } },
  topo: { ...condensedBase, means: 'Topological materials have properties protected by topology — edge states that can\'t be removed by disorder.', explore: 'Invariants, edge states, and robustness.', what: 'The band structure has a topological invariant; changing it requires closing the gap. This guarantees protected edge/surface states.', name: 'Topological — properties invariant under smooth deformation.', physical: 'Quantum Hall, topological insulators, Weyl semimetals.', quick: 'Topological materials have edge states that survive disorder — because a topological invariant protects them. They\'re key to robust quantum devices.', physics: 'Bulk-boundary correspondence: non-trivial bulk → protected edge states.', math: 'Chern number, Z₂ invariant classify phases.', equations: [{ eq: 'σ_xy = n e² / h', label: 'Quantized Hall conductance', where: 'n = Chern number' }], calculated: ['Topological invariant', 'Edge states'], used: 'Robust quantum computing, low-power electronics, spintronics.', observe: 'Edge states conduct even when the bulk is insulating; conductance is quantised.', why: 'A non-trivial topology forces gapless edge states; disorder can\'t gap them without changing the invariant.', assumptions: ['Gapped bulk', 'Defined invariant'], limitations: ['Real materials have disorder and interactions', 'Interactions can change topology'], controls: { 'Topology': { desc: 'Trivial vs non-trivial.', unit: '—' } }, viz: { 'Edge states': 'Conducting at the boundary.' } },
};

