  plasma: { ...researchBase, means: 'Plasma physics studies ionised gases — the fourth state of matter — where electromagnetic forces dominate.', explore: 'Lorentz force, E×B drift, cyclotron motion, and waves.', what: 'A plasma is a gas of free charges. Magnetic fields confine and steer them; electric fields accelerate them. Most of the universe is plasma.', name: 'Plasma — ionised gas (the fourth state).', physical: 'Charges gyrate around B fields; E×B drift is independent of charge.', quick: 'Plasma is charged gas — stars, fusion reactors, neon signs. Magnetic fields trap and steer it; electric fields drive it. Most of the universe is plasma.', physics: 'F = q(E + v×B); cyclotron ω_c = qB/m.', math: 'E×B drift: v_d = E×B/B².', equations: [{ eq: 'F = q (E + v × B)', label: 'Lorentz force' }], calculated: ['Trajectories', 'Drift velocities', 'Cyclotron frequency'], used: 'Fusion energy, space physics, astrophysics, plasma processing.', observe: 'Charges spiral around B; crossed E and B cause steady drift.', why: 'Charges feel EM forces; B bends, E accelerates — giving plasma its rich dynamics.', assumptions: ['Collisionless (or given collisions)', 'Given fields'], limitations: ['Real plasmas are collisional and kinetic', 'Many-body is hard'], controls: { 'E, B fields': { desc: 'Steer the plasma.', unit: 'V/m, T' } }, viz: { 'Particle trajectories': 'Spirals and drifts.' } },
